import{d as C,C as b,o as D,c as V,j as i,a as e,E as a,k as d,a3 as z}from"./chunks/framework.Q4yG9rk_.js";const G=JSON.parse('{"title":"庄子·盗跖","description":"从孔子往见盗跖的故事入手，辨析教导责任、劝说条件、名位安排，以及情性、生命与行为之间的关系。","frontmatter":{"title":"庄子·盗跖","description":"从孔子往见盗跖的故事入手，辨析教导责任、劝说条件、名位安排，以及情性、生命与行为之间的关系。","category":"庄子","aliases":["盗跖","庄子盗跖"],"source":["用户提供的《庄子·盗跖》原文及相关注解"]},"headers":[],"relativePath":"daoism/zhuang-zi/chapter-29.md","filePath":"daoism/zhuang-zi/chapter-29.md","lastUpdated":1792641266000}'),N={name:"daoism/zhuang-zi/chapter-29.md"},E=C({...N,setup(I){const l=[{id:"daozhi-liuxiaji",term:"柳下季",pinyin:"liǔ xià jì",meaning:"通常理解为柳下惠、展禽。另：与盗跖的兄弟关系按本篇叙述理解，不直接作为已核验的史实。"},{id:"daozhi-daozhi",term:"盗跖",pinyin:"dào zhí",meaning:"本篇故事中的盗首。另：分析其论说时，不能省略开篇的侵暴与后面的死亡威胁。"},{id:"daozhi-congzu",term:"从卒九千人",pinyin:"按句义理解",meaning:"有九千部卒跟随；从联系使人从己理解。另：数字具有叙事规模的表现作用，不直接作为历史统计。"},{id:"daozhi-qinbao",term:"侵暴",pinyin:"qīn bào",meaning:"侵扰、暴虐地侵犯。"},{id:"daozhi-xueshi",term:"穴室枢户",pinyin:"训释待辨",meaning:"大意为穿破居室、毁坏或开启门户，侵入掠夺。另：不强定每字的唯一解释。"},{id:"daozhi-rubao",term:"入保",pinyin:"rù bǎo",meaning:"进入可以防守的堡垒等处；保联系“堡”理解。"},{id:"daozhi-zhao",term:"诏",pinyin:"zhào",meaning:"告诫、教导。另：不限于帝王诏令。"},{id:"daozhi-wangshuizhi",term:"往说之",pinyin:"wǎng shuì zhī",meaning:"前去游说、劝说他。"},{id:"daozhi-judi",term:"距敌",pinyin:"jù dí",meaning:"抵御敌手；距通“拒”。"},{id:"daozhi-shifei",term:"饰非",pinyin:"shì fēi",meaning:"用言辞掩饰、辩护错误。另：有辩才不自动等于愿意检验自身。"},{id:"daozhi-yiruren",term:"易辱人以言",pinyin:"按句义理解",meaning:"轻易以言语侮辱别人。另：易不是“改变”之义。"},{id:"daozhi-biwuwang",term:"必无往",pinyin:"按句义理解",meaning:"务必不要前往；无联系“毋”理解。"},{id:"daozhi-weiyu",term:"为驭",pinyin:"wéi yù",meaning:"担任驾车者。"},{id:"daozhi-weiyou",term:"为右",pinyin:"wéi yòu",meaning:"担任车右，通常具有护卫等职责。"},{id:"daozhi-xiuzutu",term:"休卒徒",pinyin:"xiū zú tú",meaning:"使部卒休息。"},{id:"daozhi-dashanzhiyang",term:"大山之阳",pinyin:"dà shān zhī yáng",meaning:"大山南面。另：不凭此确定具体山名。"},{id:"daozhi-kuai",term:"脍",pinyin:"kuài",meaning:"把肉切细。"},{id:"daozhi-bu",term:"𫗦",pinyin:"所供音注为 bǔ",meaning:"涉及食物、进食等义，具体随句辨认。另：保留所供字形与音注，不将其用于所有语境的唯一读法。"},{id:"daozhi-baobu",term:"包𫗦",pinyin:"字形、训释待辨",meaning:"结合前后文，涉及将细切的人肝用于饮食的残酷描写。另：不强定具体烹食方式。"},{id:"daozhi-yezhe",term:"谒者",pinyin:"yè zhě",meaning:"负责传达求见请求的人。"},{id:"daozhi-tong",term:"通",pinyin:"tōng",meaning:"通报求见请求。"},{id:"daozhi-xiaoti",term:"孝弟",pinyin:"xiào tì",meaning:"孝顺父母、敬爱兄长；弟通“悌”。"},{id:"daozhi-dexingyuji",term:"得幸于季",pinyin:"按句义理解",meaning:"承蒙柳下季厚待，与其有交情。"},{id:"daozhi-wanglv",term:"望履幕下",pinyin:"训释待辨",meaning:"求得在帐下拜见的谦敬说法。"},{id:"daozhi-bixifanzou",term:"避席反走",pinyin:"训释待辨",meaning:"表现退避、趋行等恭敬动作。另：反走不直接按现代“逃跑”理解。"},{id:"daozhi-anjian",term:"案剑",pinyin:"àn jiàn",meaning:"按着剑；案通“按”。"},{id:"daozhi-chenmu",term:"瞋目",pinyin:"chēn mù",meaning:"睁大眼睛怒视。"},{id:"daozhi-ruhu",term:"乳虎",pinyin:"rǔ hǔ",meaning:"哺育幼虎的母虎，形容声势凶猛。"},{id:"daozhi-sande",term:"三德",pinyin:"sān dé",meaning:"孔子在本段提出的长大美好、才智辨析、勇悍率众三类条件。另：这里的德不只指现代意义的道德善行；也不直接当作完整的任君标准。"},{id:"daozhi-jieyuezhi",term:"皆说之",pinyin:"jiē yuè zhī",meaning:"都喜欢他；说通“悦”。"},{id:"daozhi-zhiweitiandi",term:"知维天地",pinyin:"知读 zhì",meaning:"才智足以统摄、通达天地；知通“智”。"},{id:"daozhi-bianzhuwu",term:"辩诸物",pinyin:"biàn zhū wù",meaning:"辨析万物；辩联系“辨”理解。"},{id:"daozhi-nanmian",term:"南面称孤",pinyin:"nán miàn chēng gū",meaning:"居君主之位，面南而坐，自称孤。"},{id:"daozhi-jidan",term:"激丹",pinyin:"jī dān",meaning:"鲜明的丹红色，形容唇色。"},{id:"daozhi-qibei",term:"齐贝",pinyin:"qí bèi",meaning:"排列整齐的贝壳，形容牙齿。"},{id:"daozhi-yinzhong",term:"音中黄钟",pinyin:"yīn zhòng huáng zhōng",meaning:"声音与黄钟之律相合，形容洪亮、和谐。"},{id:"daozhi-chibuqu",term:"耻不取焉",pinyin:"句义、训释待辨",meaning:"联系前文，可把握为孔子对“盗跖”之名与所赞条件不相称的羞耻、可惜之意。另：基本语意可由劝说上下文把握，不强定逐字解释。"},{id:"daozhi-youyitingchen",term:"有意听臣",pinyin:"按句义理解",meaning:"愿意听取我的意见。"},{id:"daozhi-gengshi",term:"更始",pinyin:"gēng shǐ",meaning:"重新开始，改变原有局面。"},{id:"daozhi-kundi",term:"昆弟",pinyin:"kūn dì",meaning:"兄弟。另：收养昆弟的具体对象不宜过度限定。"},{id:"daozhi-guiyili",term:"规以利",pinyin:"guī yǐ lì",meaning:"用利益引导，谋求使人改变。"},{id:"daozhi-hengmin",term:"恒民",pinyin:"héng mín",meaning:"普通民众。另：盗跖在这里带有轻蔑语气。"},{id:"daozhi-hengminxuwo",term:"恒民畜我",pinyin:"畜联系畜养义理解",meaning:"把我当普通人一样收纳、控制。另：是盗跖对封侯安排的解释，不等于一切给予都必然是控制。"},{id:"daozhi-yide",term:"遗德",pinyin:"yí dé",meaning:"父母遗传、留给自己的禀赋。另：此处不只指道德善行。"},{id:"daozhi-zhizhuizhidi",term:"置锥之地",pinyin:"zhì zhuī zhī dì",meaning:"极小的立足之地。"},{id:"daozhi-xiangli",term:"橡栗",pinyin:"xiàng lì",meaning:"橡实与栗子等食物。"},{id:"daozhi-yang",term:"炀",pinyin:"yàng",meaning:"烤火、取暖。"},{id:"daozhi-juju-yuyu",term:"居居·于于",pinyin:"jū jū · yú yú",meaning:"安处、舒缓自得的样子。另：具体训释可有差异。"},{id:"daozhi-lingruo",term:"陵弱",pinyin:"líng ruò",meaning:"欺凌弱者；陵联系“凌”理解。"},{id:"daozhi-fengyiqiandai",term:"缝衣浅带",pinyin:"服饰形制待辨",meaning:"对儒者服饰的描述。另：具体形制不强定。"},{id:"daozhi-gancishuizilu",term:"甘辞说子路",pinyin:"说读 shuì",meaning:"用悦耳之辞劝说子路。"},{id:"daozhi-weiguan",term:"危冠",pinyin:"wēi guān",meaning:"高冠；危有高义。"},{id:"daozhi-zu",term:"菹",pinyin:"zū",meaning:"本为切碎腌制之物，此处指被剁成肉酱的残酷结局。"},{id:"daozhi-youli",term:"羑里",pinyin:"yǒu lǐ",meaning:"地名，传说中文王被拘禁之处。另：原文保留所供音注形式。"},{id:"daozhi-shulunzhi",term:"孰论之",pinyin:"训释待辨",meaning:"通常联系仔细审察、熟加论究理解。"},{id:"daozhi-pianku",term:"偏枯",pinyin:"piān kū",meaning:"一侧身体枯病、失常，也联系劳损理解。另：不据此作现代医学诊断。"},{id:"daozhi-shixingfeishi",term:"饰行非世",pinyin:"按句义理解",meaning:"刻意树立、修饰行为，并非议世俗。"},{id:"daozhi-fan",term:"燔",pinyin:"fán",meaning:"焚烧。"},{id:"daozhi-qiyuliangxia",term:"期于梁下",pinyin:"按句义理解",meaning:"约定在桥下相见。"},{id:"daozhi-zhequanliushi",term:"磔犬流豕",pinyin:"训释待辨",meaning:"涉及被杀弃的犬、漂流的猪等卑贱形象。另：是强烈贬斥之辞，不作为中性的人物评价。"},{id:"daozhi-limingqingsi",term:"离名轻死",pinyin:"离常联系“罹”理解",meaning:"系于名、受名所累而轻视死亡。另：是盗跖对所列人物的评价，不能直接当作其动机已被证实。"},{id:"daozhi-benyangshouming",term:"本养寿命",pinyin:"按句义理解",meaning:"以养护寿命为根本。"},{id:"daozhi-bingshou",term:"病瘦",pinyin:"bìng shòu",meaning:"疾病、衰弱等处境。"},{id:"daozhi-youshizhiju",term:"有时之具",pinyin:"按句义理解",meaning:"具有有限寿命的身体，与无穷天地相对。"},{id:"daozhi-qiji",term:"骐骥",pinyin:"qí jì",meaning:"良马。"},{id:"daozhi-yueqizhiyi",term:"说其志意",pinyin:"yuè qí zhì yì",meaning:"使自己的志意悦适；说通“悦”。"},{id:"daozhi-quanzhen",term:"全真",pinyin:"quán zhēn",meaning:"保全真实、本然的情性与生命。另：不只指说真话，也不等于认可盗跖的全部行为。"},{id:"daozhi-jiqu",term:"亟去",pinyin:"jí qù",meaning:"赶快离去。"},{id:"daozhi-kuangkuangjiji",term:"狂狂汲汲",pinyin:"按句义理解",meaning:"狂乱、急迫经营的样子。"},{id:"daozhi-pei",term:"辔",pinyin:"pèi",meaning:"驾驭车马的缰绳。"},{id:"daozhi-mangran",term:"芒然",pinyin:"máng rán",meaning:"恍惚、茫然；芒联系“茫”理解。"},{id:"daozhi-shi",term:"轼",pinyin:"shì",meaning:"车前供凭倚的横木。"},{id:"daozhi-queran",term:"阙然",pinyin:"quē rán",meaning:"久未相见、间隔的样子。"},{id:"daozhi-dewei",term:"得微……邪",pinyin:"按句式理解",meaning:"莫非……吗？表示试探性询问。"},{id:"daozhi-jiu",term:"灸",pinyin:"jiǔ",meaning:"灸治；无病自灸比喻无故自取痛苦。"},{id:"daozhi-liaohu-bianhu",term:"料虎头·编虎须",pinyin:"字义、异文待辨",meaning:"大意为触弄虎头、虎须，形容贸然冒险。另：不强定每字的唯一训释。"},{id:"daozhi-zizhang",term:"子张",pinyin:"zǐ zhāng",meaning:"孔子弟子。"},{id:"daozhi-mangoude",term:"满苟得",pinyin:"mǎn gǒu dé",meaning:"对话人物。另：称名可引出苟求有得的联想，不仅凭名字判定全部立场。"},{id:"daozhi-he",term:"盍",pinyin:"hé",meaning:"何不、为什么不。"},{id:"daozhi-weixing",term:"为行",pinyin:"wéi xíng",meaning:"修行、实行合宜的行为。另：不是现代“举行活动”。"},{id:"daozhi-buxin",term:"不信",pinyin:"bù xìn",meaning:"不被相信、不能取信于人。"},{id:"daozhi-buren",term:"不任",pinyin:"bù rèn",meaning:"不被任用、托付。"},{id:"daozhi-duoxin",term:"多信者显",pinyin:"信的训释待辨",meaning:"本组“信”有联系伸张、自我伸显等理解的读法。另：不直接沿用前句取信义，也不径译为诚信者显达。"},{id:"daozhi-jizai",term:"几在",pinyin:"jī zài",meaning:"大抵在于、接近取决于。"},{id:"daozhi-baoqitian",term:"抱其天",pinyin:"bào qí tiān",meaning:"持守自身天然、本然的情性。"},{id:"daozhi-zangju",term:"臧聚",pinyin:"zāng jù",meaning:"通常联系仆役、地位低下者理解。另：具体称谓有训释问题。"},{id:"daozhi-zuose",term:"怍色",pinyin:"zuò sè",meaning:"羞愧的神色。"},{id:"daozhi-bianrong",term:"变容易色",pinyin:"按句义理解",meaning:"改变面容、神色。另：易为动词，不按现代“容易”拆解。"},{id:"daozhi-chengbuzu",term:"称不足",pinyin:"chēng bù zú",meaning:"自称不及、不足以当此称赞。"},{id:"daozhi-xiaobai",term:"小白",pinyin:"xiǎo bái",meaning:"齐桓公之名。"},{id:"daozhi-rusao",term:"入嫂",pinyin:"训释随语境辨认",meaning:"此处为有关不正当男女关系的指控。另：按人物论辩材料理解，不直接当作已核验史实。"},{id:"daozhi-tianchengzi",term:"田成子常",pinyin:"人物称名",meaning:"田常，谥成；本段称其杀君窃国。"},{id:"daozhi-shoubi",term:"受币",pinyin:"shòu bì",meaning:"接受财物、礼物。另：币不只指现代货币；受礼不自动等于认可对方全部行为。"},{id:"daozhi-xingzexiazhi",term:"行则下之",pinyin:"按句义理解",meaning:"行动中却屈居其下、依附或尊事之。"},{id:"daozhi-beizhan",term:"悖战",pinyin:"bèi zhàn",meaning:"相互违背、冲突。"},{id:"daozhi-fu",term:"拂",pinyin:"fú",meaning:"违逆、不协调。"},{id:"daozhi-shuyue",term:"《书》曰",pinyin:"shū yuē",meaning:"引述一种成文说法。另：不强定出自今本《尚书》的某篇。"},{id:"daozhi-shuqi",term:"疏戚",pinyin:"shū qī",meaning:"疏远者与亲近者。"},{id:"daozhi-wujiliuwei",term:"五纪六位",pinyin:"具体分类待辨",meaning:"人伦秩序及亲属、尊卑等名分。另：不强定唯一分类。"},{id:"daozhi-wangjiweidi",term:"王季为适",pinyin:"适联系“嫡”理解",meaning:"王季成为嫡嗣、继承者。"},{id:"daozhi-jianyudao",term:"监于道",pinyin:"jiān yú dào",meaning:"以道为鉴、受到道的检验。"},{id:"daozhi-songyuwuyue",term:"吾日与子讼于无约",pinyin:"字义、异文待辨",meaning:"结合上下文，涉及双方争论及其判断根据。另：不凭一套流畅译文强定所有字义。"},{id:"daozhi-xun",term:"殉",pinyin:"xùn",meaning:"以自身追随、牺牲于某个目标。另：不限于实际死亡，也不把一切求取与行义都视为殉。"},{id:"daozhi-er-secondperson",term:"而天·而行·而义",pinyin:"而常作第二人称",meaning:"此类“而”可联系“你的……”理解。另：须结合韵语，不将所有“而”一概作此解释。"},{id:"daozhi-ruowangruozhi",term:"若枉若直",pinyin:"用法待辨",meaning:"可联系你所认为的曲与直理解。另：若的具体用法须结合韵语辨认。"},{id:"daozhi-xiaoxi",term:"消息",pinyin:"xiāo xī",meaning:"消长、进退变化。另：不是现代新闻信息。"},{id:"daozhi-yuanji",term:"圆机",pinyin:"yuán jī",meaning:"圆转、灵活应变的枢机，不固执于单一端点。"},{id:"daozhi-jueyan",term:"抉眼",pinyin:"jué yǎn",meaning:"挖出眼睛，关联子胥故事。"},{id:"daozhi-zhigongzhengfu",term:"直躬证父",pinyin:"按句义理解",meaning:"直躬出面告发、作证父亲的过错，关联传统故事。"},{id:"daozhi-baozishenzi",term:"鲍子·申子",pinyin:"人物所指随语境辨认",meaning:"通常联系鲍焦、申徒狄理解。另：简约事迹不补成完整传记。"},{id:"daozhi-kuangzi",term:"匡子",pinyin:"人物所指待辨",meaning:"人物所指及相关事迹有解释分歧。另：不强定身份与完整经历。"},{id:"daozhi-biqixing",term:"必其行",pinyin:"按句义理解",meaning:"坚决落实、务必实行其行为，有不容转圜的意味。"},{id:"daozhi-liqihuan",term:"离其患",pinyin:"离联系“罹”理解",meaning:"遭遇其祸患。"},{id:"daozhi-wuzu",term:"无足",pinyin:"wú zú",meaning:"对话人物，称名与不知满足的方向相呼应。另：不只凭名字代替对发言的分析。"},{id:"daozhi-zhihe",term:"知和",pinyin:"zhī hé",meaning:"对话人物，称名与和适、分寸的方向相呼应。"},{id:"daozhi-zu-finally",term:"卒",pinyin:"zú",meaning:"终究、到底。"},{id:"daozhi-xingmingjiuli",term:"兴名就利",pinyin:"按句义理解",meaning:"兴起名声、趋就利益。"},{id:"daozhi-renguizhi",term:"人归之",pinyin:"按句义理解",meaning:"人们归附、趋向他。"},{id:"daozhi-xiazhi",term:"下之",pinyin:"按句义理解",meaning:"居于其下，对其表示服从。"},{id:"daozhi-jianxiagui",term:"见下贵",pinyin:"按句义理解",meaning:"被人尊奉、看重；见表示被动。"},{id:"daozhi-antileyi",term:"安体乐意",pinyin:"ān tǐ lè yì",meaning:"使身体安适，使心意悦乐。"},{id:"daozhi-gouwei",term:"苟为·苟不为",pinyin:"按句义理解",meaning:"不辨根据地去做，或不辨根据地拒绝做。"},{id:"daozhi-dongyibaixing",term:"动以百姓",pinyin:"训释待辨",meaning:"此处有字义、解释问题。另：以下解读以“不违其度”及不足、有余的上下文为据，不強定为唯一的公共治理含义。"},{id:"daozhi-du",term:"度",pinyin:"dù",meaning:"分寸、限度、合宜的尺度。"},{id:"daozhi-buziyiweitan",term:"不自以为贪",pinyin:"按句义理解",meaning:"不将必要的求取理解为贪，也不只以贪的名号自限。另：并非自称不足便能使一切求取合宜。"},{id:"daozhi-buziyiweilian",term:"不自以为廉",pinyin:"按句义理解",meaning:"不把辞去多余经营为廉名。"},{id:"daozhi-powai",term:"迫外",pinyin:"按句义理解",meaning:"受外在评价、名号等逼迫。"},{id:"daozhi-fanjianzhidu",term:"反监之度",pinyin:"按句义理解",meaning:"回过来以实际分寸为鉴，进行检验。"},{id:"daozhi-mei",term:"美",pinyin:"měi",meaning:"美好之物、美名等。另：本段不只限定为容貌。"},{id:"daozhi-shi-affair",term:"事",pinyin:"shì",meaning:"所从事、经营的事务。"},{id:"daozhi-kutijuegan",term:"苦体绝甘",pinyin:"按句义理解",meaning:"使身体受苦，断绝甘美享用。"},{id:"daozhi-yueyang",term:"约养",pinyin:"yuē yǎng",meaning:"缩减、限制生活供养。另：不将一切节俭与适度节制都判为有害。"},{id:"daozhi-ping",term:"平",pinyin:"píng",meaning:"平适、适量。另：不是人人财物完全相等。"},{id:"daozhi-youyu",term:"有余",pinyin:"yǒu yú",meaning:"此处联系超过合宜限度理解。另：不把一切储备直接归入有害过量。"},{id:"daozhi-liuhai",term:"六害",pinyin:"liù hài",meaning:"乱、苦、疾、辱、忧、畏六类损害。另：本文所据材料未提供六害的完整原文，正文依用户提供的解读概括，不冒充逐字翻译。"}],y=[{id:"daozhi-01",label:"孔子往见：劝阻、求见与封侯方案",sentences:[["孔子与",{text:"柳下季",glossary:"daozhi-liuxiaji"},"为友，柳下季之弟名曰",{text:"盗跖",glossary:"daozhi-daozhi"},"。盗跖",{text:"从卒九千人",glossary:"daozhi-congzu"},"，横行天下，",{text:"侵暴",glossary:"daozhi-qinbao"},"诸侯。",{text:"穴室枢户",glossary:"daozhi-xueshi"},"，驱人牛马，取人妇女。贪得忘亲，不顾父母兄弟，不祭先祖。所过之邑，大国守城，小国",{text:"入保",glossary:"daozhi-rubao"},"，万民苦之。"],["孔子谓柳下季曰：“夫为人父者，必能",{text:"诏",glossary:"daozhi-zhao"},"其子；为人兄者，必能教其弟。若父不能诏其子，兄不能教其弟，则无贵父子兄弟之亲矣。今先生，世之才士也，弟为盗跖，为天下害，而弗能教也，丘窃为先生羞之。丘请为先生",{text:"往说之",glossary:"daozhi-wangshuizhi"},"。”"],["柳下季曰：“先生言为人父者必能诏其子，为人兄者必能教其弟，若子不听父之诏，弟不受兄之教，虽今先生之辩，将奈之何哉？且跖之为人也，心如涌泉，意如飘风，强足以",{text:"距敌",glossary:"daozhi-judi"},"，辩足以",{text:"饰非",glossary:"daozhi-shifei"},"。顺其心则喜，逆其心则怒，",{text:"易辱人以言",glossary:"daozhi-yiruren"},"。先生",{text:"必无往",glossary:"daozhi-biwuwang"},"。”孔子不听，颜回",{text:"为驭",glossary:"daozhi-weiyu"},"，子贡",{text:"为右",glossary:"daozhi-weiyou"},"，往见盗跖。"],["盗跖乃方",{text:"休卒徒",glossary:"daozhi-xiuzutu"},{text:"大山之阳",glossary:"daozhi-dashanzhiyang"},"，",{text:"脍",glossary:"daozhi-kuai"},"人肝而",{text:"包𫗦（音ｂｕ３）之",glossary:"daozhi-baobu"},"。孔子下车而前，见",{text:"谒者",glossary:"daozhi-yezhe"},"曰：“鲁人孔丘，闻将军高义，敬再拜谒者。”谒者入",{text:"通",glossary:"daozhi-tong"},"。"],["盗跖闻之大怒，目如明星，发上指冠，曰：“此夫鲁国之巧伪人孔丘非邪？为我告之：尔作言造语，妄称文、武，冠枝木之冠，带死牛之胁，多辞缪说，不耕而食，不织而衣，摇唇鼓舌，擅生是非，以迷天下之主，使天下学士不反其本，妄作",{text:"孝弟",glossary:"daozhi-xiaoti"},"，而侥幸于封侯富贵者也。子之罪大极重，疾走归！不然，我将以子肝益昼",{text:"𫗦",glossary:"daozhi-bu"},"之膳。”"],["孔子复通曰：“丘",{text:"得幸于季",glossary:"daozhi-dexingyuji"},"，愿",{text:"望履幕下",glossary:"daozhi-wanglv"},"。”谒者复通。盗跖曰：“使来前！”孔子趋而进，",{text:"避席反走",glossary:"daozhi-bixifanzou"},"，再拜盗跖。盗跖大怒，两展其足，",{text:"案剑",glossary:"daozhi-anjian"},{text:"瞋目",glossary:"daozhi-chenmu"},"，声如",{text:"乳虎",glossary:"daozhi-ruhu"},"，曰：“丘来前！若所言顺吾意则生，逆吾心则死。”"],["孔子曰：“丘闻之，凡天下有",{text:"三德",glossary:"daozhi-sande"},"：生而长大，美好无双，少长贵贱见而",{text:"皆说之",glossary:"daozhi-jieyuezhi"},"，此上德也；",{text:"知维天地",glossary:"daozhi-zhiweitiandi"},"，能",{text:"辩诸物",glossary:"daozhi-bianzhuwu"},"，此中德也；勇悍果敢，聚众率兵，此下德也。凡人有此一德者，足以",{text:"南面称孤",glossary:"daozhi-nanmian"},"矣。"],["今将军兼此三者，身长八尺二寸，面目有光，唇如",{text:"激丹",glossary:"daozhi-jidan"},"，齿如",{text:"齐贝",glossary:"daozhi-qibei"},"，",{text:"音中黄钟",glossary:"daozhi-yinzhong"},"，而名曰盗跖，丘窃为将军",{text:"耻不取焉",glossary:"daozhi-chibuqu"},"。"],["将军",{text:"有意听臣",glossary:"daozhi-youyitingchen"},"，臣请南使吴越，北使齐鲁，东使宋卫，西使晋楚，使为将军造大城数百里，立数十万户之邑，尊将军为诸侯，与天下",{text:"更始",glossary:"daozhi-gengshi"},"，罢兵休卒，收养",{text:"昆弟",glossary:"daozhi-kundi"},"，共祭先祖。此圣人才士之行，而天下之愿也。”"]]},{id:"daozhi-02",label:"盗跖反击：名位、情性与有限生命",sentences:[["盗跖大怒曰：“丘来前！夫可",{text:"规以利",glossary:"daozhi-guiyili"},"而可谏以言者，皆愚陋",{text:"恒民",glossary:"daozhi-hengmin"},"之谓耳。今长大美好，人见而悦之者，此吾父母之",{text:"遗德",glossary:"daozhi-yide"},"也，丘虽不吾誉，吾独不自知邪？且吾闻之，好面誉人者，亦好背而毁之。今丘告我以大城众民，是欲规我以利而",{text:"恒民畜我",glossary:"daozhi-hengminxuwo"},"也，安可久长也！"],["城之大者，莫大乎天下矣。尧、舜有天下，子孙无",{text:"置锥之地",glossary:"daozhi-zhizhuizhidi"},"；汤、武立为天子，而后世绝灭。非以其利大故邪？"],["且吾闻之，古者禽兽多而人少，于是民皆巢居以避之。昼拾",{text:"橡栗",glossary:"daozhi-xiangli"},"，暮栖木上，故命之曰‘有巢氏之民’。古者民不知衣服，夏多积薪，冬则",{text:"炀",glossary:"daozhi-yang"},"之，故命之曰‘知生之民’。神农之世，卧则",{text:"居居",glossary:"daozhi-juju-yuyu"},"，起则",{text:"于于",glossary:"daozhi-juju-yuyu"},"。民知其母，不知其父，与麋鹿共处，耕而食，织而衣，无有相害之心。此至德之隆也。"],["然而黄帝不能致德，与蚩由战于涿鹿之野，流血百里。尧、舜作，立群臣，汤放其主，武王杀纣。自是之后，以强",{text:"陵弱",glossary:"daozhi-lingruo"},"，以众暴寡。汤、武以来，皆乱人之徒也。"],["今子修文、武之道，掌天下之辩，以教后世。",{text:"缝衣浅带",glossary:"daozhi-fengyiqiandai"},"，矫言伪行，以迷惑天下之主，而欲求富贵焉。盗莫大于子，天下何故不谓子为盗丘，而乃谓我为盗跖？"],["子以",{text:"甘辞说子路",glossary:"daozhi-gancishuizilu"},"而使从之。使子路去其",{text:"危冠",glossary:"daozhi-weiguan"},"，解其长剑，而受教于子。天下皆曰：‘孔丘能止暴禁非。’其卒之也，子路欲杀卫君而事不成，身",{text:"菹",glossary:"daozhi-zu"},"于卫东门之上，是子教之不至也。子自谓才士圣人邪，则再逐于鲁，削迹于卫，穷于齐，围于陈蔡，不容身于天下。子教子路菹。此患，上无以为身，下无以为人。子之道岂足贵邪？"],["世之所高，莫若黄帝。黄帝尚不能全德，而战于涿鹿之野，流血百里。尧不慈，舜不孝，禹",{text:"偏枯",glossary:"daozhi-pianku"},"，汤放其主，武王伐纣，文王拘",{text:"羑（音ｙｏｕ３）里",glossary:"daozhi-youli"},"。此六子者，世之所高也。",{text:"孰论之",glossary:"daozhi-shulunzhi"},"，皆以利惑其真而强反其情性，其行乃甚可羞也。"],["世之所谓贤士：伯夷、叔齐。伯夷、叔齐辞孤竹之君，而饿死于首阳之山，骨肉不葬。鲍焦",{text:"饰行非世",glossary:"daozhi-shixingfeishi"},"，抱木而死。申徒狄谏而不听，负石自投于河，为鱼鳖所食。介子推至忠也，自割其股以食文公。文公后背之，子推怒而去，抱木而",{text:"燔",glossary:"daozhi-fan"},"死。尾生与女子",{text:"期于梁下",glossary:"daozhi-qiyuliangxia"},"，女子不来，水至不去，抱梁柱而死。此六子者，无异于",{text:"磔犬流豕",glossary:"daozhi-zhequanliushi"},"、操瓢而乞者，皆",{text:"离名轻死",glossary:"daozhi-limingqingsi"},"，不念",{text:"本养寿命",glossary:"daozhi-benyangshouming"},"者也。"],["世之所谓忠臣者，莫若王子比干、伍子胥。子胥沉江，比干剖心。此二子者，世谓忠臣也，然卒为天下笑。自上观之，至于子胥、比干，皆不足贵也。"],["丘之所以说我者，若告我以鬼事，则我不能知也；若告我以人事者，不过此矣，皆吾所闻知也。今吾告子以人之情：目欲视色，耳欲听声，口欲察味，志气欲盈。"],["人上寿百岁，中寿八十，下寿六十，除",{text:"病瘦",glossary:"daozhi-bingshou"},"死丧忧患，其中开口而笑者，一月之中不过四五日而已矣。天与地无穷，人死者有时。操",{text:"有时之具",glossary:"daozhi-youshizhiju"},"，而托于无穷之间，忽然无异",{text:"骐骥",glossary:"daozhi-qiji"},"之驰过隙也。"],["不能",{text:"说其志意",glossary:"daozhi-yueqizhiyi"},"、养其寿命者，皆非通道者也。丘之所言，皆吾之所弃也。",{text:"亟去",glossary:"daozhi-jiqu"},"走归，无复言之！子之道",{text:"狂狂汲汲",glossary:"daozhi-kuangkuangjiji"},"，诈巧虚伪事也，非可以",{text:"全真",glossary:"daozhi-quanzhen"},"也，奚足论哉！”"],["孔子再拜趋走，出门上车，执",{text:"辔",glossary:"daozhi-pei"},"三失，目",{text:"芒然",glossary:"daozhi-mangran"},"无见，色若死灰，据",{text:"轼",glossary:"daozhi-shi"},"低头，不能出气。"],["归到鲁东门外，适遇柳下季。柳下季曰：“今者",{text:"阙然",glossary:"daozhi-queran"},"，数日不见，车马有行色，",{text:"得微往见跖邪",glossary:"daozhi-dewei"},"？”孔子仰天而叹曰：“然！”柳下季曰：“跖得无逆汝意若前乎？”孔子曰：“然。丘所谓无病而自",{text:"灸",glossary:"daozhi-jiu"},"也。疾走",{text:"料虎头",glossary:"daozhi-liaohu-bianhu"},"，",{text:"编虎须",glossary:"daozhi-liaohu-bianhu"},"，几不免虎口哉！”"]]},{id:"daozhi-03",label:"子张与满苟得：行义、名利与情性",sentences:[[{text:"子张",glossary:"daozhi-zizhang"},"问于",{text:"满苟得",glossary:"daozhi-mangoude"},"曰：“",{text:"盍",glossary:"daozhi-he"},"不",{text:"为行",glossary:"daozhi-weixing"},"？无行则",{text:"不信",glossary:"daozhi-buxin"},"，不信则",{text:"不任",glossary:"daozhi-buren"},"，不任则不利。故观之名，计之利，而义真是也。若弃名利，反之于心，则夫士之为行，不可一日不为乎！”"],["满苟得曰：“无耻者富，",{text:"多信者显",glossary:"daozhi-duoxin"},"。夫名利之大者，",{text:"几在",glossary:"daozhi-jizai"},"无耻而信。故观之名，计之利，而信真是也。若弃名利，反之于心，则夫士之为行，",{text:"抱其天",glossary:"daozhi-baoqitian"},"乎！”"],["子张曰：“昔者桀、纣贵为天子，富有天下。今谓",{text:"臧聚",glossary:"daozhi-zangju"},"曰：‘汝行如桀、纣。’则有",{text:"怍色",glossary:"daozhi-zuose"},"，有不服之心者，小人所贱也。仲尼、墨翟，穷为匹夫，今谓宰相曰‘子行如仲尼、墨翟。’则",{text:"变容易色",glossary:"daozhi-bianrong"},"，",{text:"称不足",glossary:"daozhi-chengbuzu"},"者，士诚贵也。故势为天子，未必贵也；穷为匹夫，未必贱也。贵贱之分，在行之美恶。”"],["满苟得曰：“小盗者拘，大盗者为诸侯。诸侯之门，义士存焉。昔者桓公",{text:"小白",glossary:"daozhi-xiaobai"},"杀兄",{text:"入嫂",glossary:"daozhi-rusao"},"，而管仲为臣；",{text:"田成子常",glossary:"daozhi-tianchengzi"},"杀君窃国，而孔子",{text:"受币",glossary:"daozhi-shoubi"},"。论则贱之，",{text:"行则下之",glossary:"daozhi-xingzexiazhi"},"，则是言行之情",{text:"悖战",glossary:"daozhi-beizhan"},"于胸中也，不亦",{text:"拂",glossary:"daozhi-fu"},"乎！故",{text:"《书》曰",glossary:"daozhi-shuyue"},"：‘孰恶孰美，成者为首，不成者为尾。’”"],["子张曰：“子不为行，即将",{text:"疏戚",glossary:"daozhi-shuqi"},"无伦，贵贱无义，长幼无序。",{text:"五纪六位",glossary:"daozhi-wujiliuwei"},"，将何以为别乎？”"],["满苟得曰：“尧杀长子，舜流母弟，疏戚有伦乎？汤放桀，武王杀纣，贵贱有义乎？",{text:"王季为适",glossary:"daozhi-wangjiweidi"},"，周公杀兄，长幼有序乎？儒者伪辞，墨子兼爱，五纪六位，将有别乎？且子正为名，我正为利。名利之实，不顺于理，不",{text:"监于道",glossary:"daozhi-jianyudao"},"。"],[{text:"吾日与子讼于无约",glossary:"daozhi-songyuwuyue"},"，曰‘小人",{text:"殉",glossary:"daozhi-xun"},"财，君子殉名，其所以变其情、易其性则异矣；乃至于弃其所为而殉其所不为则一也。’"],["故曰：无为小人，反殉",{text:"而天",glossary:"daozhi-er-secondperson"},"；无为君子，从天之理。",{text:"若枉若直",glossary:"daozhi-ruowangruozhi"},"，相而天极。面观四方，与时",{text:"消息",glossary:"daozhi-xiaoxi"},"。若是若非，执而",{text:"圆机",glossary:"daozhi-yuanji"},"。独成而意，与道徘徊。无转",{text:"而行",glossary:"daozhi-er-secondperson"},"，无成",{text:"而义",glossary:"daozhi-er-secondperson"},"，将失而所为。无赴而富，无殉而成，将弃而天。"],["比干剖心，子胥",{text:"抉眼",glossary:"daozhi-jueyan"},"，忠之祸也；",{text:"直躬证父",glossary:"daozhi-zhigongzhengfu"},"，尾生溺死，信之患也；",{text:"鲍子",glossary:"daozhi-baozishenzi"},"立干，",{text:"申子",glossary:"daozhi-baozishenzi"},"不自理，廉之害也；孔子不见母，",{text:"匡子",glossary:"daozhi-kuangzi"},"不见父，义之失也。此上世之所传、下世之所语以为士者，正其言，",{text:"必其行",glossary:"daozhi-biqixing"},"，故服其殃、",{text:"离其患",glossary:"daozhi-liqihuan"},"也。”"]]},{id:"daozhi-04-excerpts",label:"无足与知和：关键句摘录，非连续全文",sentences:[[{text:"无足",glossary:"daozhi-wuzu"},"问于",{text:"知和",glossary:"daozhi-zhihe"},"曰：“人",{text:"卒",glossary:"daozhi-zu-finally"},"未有不",{text:"兴名就利",glossary:"daozhi-xingmingjiuli"},"者。彼富则",{text:"人归之",glossary:"daozhi-renguizhi"},"，归则",{text:"下之",glossary:"daozhi-xiazhi"},"，下则贵之。夫",{text:"见下贵",glossary:"daozhi-jianxiagui"},"者，所以长生",{text:"安体乐意",glossary:"daozhi-antileyi"},"之道也。”"],["“故不为",{text:"苟为",glossary:"daozhi-gouwei"},"，不为",{text:"苟不为",glossary:"daozhi-gouwei"},"。”"],["“夫名誉之欲，富贵之求，人之所欲也。”"],["“知者之为，故",{text:"动以百姓",glossary:"daozhi-dongyibaixing"},"，不违其",{text:"度",glossary:"daozhi-du"},"，是以足而不争，无以为故不求。不足故求之，争四处而",{text:"不自以为贪",glossary:"daozhi-buziyiweitan"},"；有余故辞之，弃天下而",{text:"不自以为廉",glossary:"daozhi-buziyiweilian"},"。廉贪之实，非以",{text:"迫外",glossary:"daozhi-powai"},"也，",{text:"反监之度",glossary:"daozhi-fanjianzhidu"},"。”"],["“不以",{text:"美",glossary:"daozhi-mei"},"害生，不以",{text:"事",glossary:"daozhi-shi-affair"},"害己。”"],["“今为清名而",{text:"苦体绝甘",glossary:"daozhi-kutijuegan"},"，",{text:"约养",glossary:"daozhi-yueyang"},"以持生，则亦不若久贫矣！”"],["无足曰：“夫富之于人，无所不利……”"],["知和曰：“",{text:"平",glossary:"daozhi-ping"},"为福，",{text:"有余",glossary:"daozhi-youyu"},"为害者，物莫不然，而财其甚者也。”"],["“今富人有此",{text:"六害",glossary:"daozhi-liuhai"},"，而汝不知。”"]]}],m=[{id:"daozhi-guide-01-01",text:"万民苦之。",guide:"开篇明确写出侵暴及其受害者，后面的雄辩不能抹去这一背景。",note:"批评他人有根据，不自动使自己的暴行正当；行为残暴也不使全部批评失去分析价值。"},{id:"daozhi-guide-01-02",text:"必能诏其子；必能教其弟。",guide:"孔子将亲属教导责任与教化结果紧密相连，柳下季随后提出听者可能不受教。",note:"他人未改，不足以单独证明教导者未尽责。"},{id:"daozhi-guide-01-03",text:"若子不听父之诏，弟不受兄之教……将奈之何哉？",guide:"有教导责任，不等于有保证别人听从的能力。",note:"不是说从此无需关心或教导。"},{id:"daozhi-guide-01-04",text:"强足以距敌，辩足以饰非。",guide:"劝说效果既受强力限制，也受听者如何使用辩才影响。",note:"这是柳下季的评价，不能据此预判后面每项反驳都是狡辩。"},{id:"daozhi-guide-01-05",text:"闻将军高义。",guide:"称誉承担求得会面、打开对话的作用，与开篇暴行形成反差。",note:"不直接证明孔子认可全部暴行，也不直接证明礼貌全是虚伪。"},{id:"daozhi-guide-01-06",text:"顺吾意则生，逆吾心则死。",guide:"盗跖以生命威胁控制对话，而劝说本来需要触动现有判断，双方条件冲突。",note:"后续不能仅作为无压力的平等论辩理解。"},{id:"daozhi-guide-01-07",text:"今将军兼此三者。",guide:"孔子先承认容貌、才智、勇力等条件，再将其转向另一种政治身份。",note:"三德不全等于现代道德品质，也不是完整的统治者资格论证。"},{id:"daozhi-guide-01-08",text:"尊将军为诸侯，与天下更始。",guide:"城邑、名位、罢兵与养亲共同构成改变方案，回应开篇暴行。",note:"方案确实以利益吸引，但原文未证明其可行，也未得到盗跖认可。"},{id:"daozhi-guide-02-01",text:"丘虽不吾誉，吾独不自知邪？",guide:"盗跖不愿依赖孔子的称誉确认自身禀赋。",note:"对禀赋自知不等于充分反省全部行为。"},{id:"daozhi-guide-02-02",text:"规我以利而恒民畜我。",guide:"封侯安排被解释为利诱与收纳，而非单纯改善生活。",note:"“恒民”带轻蔑语气，不将其全部美化为平等、开放的独立。"},{id:"daozhi-guide-02-03",text:"无有相害之心。此至德之隆也。",guide:"盗跖用不相害的早期生活反衬政治传统中的争夺。",note:"这是评价性古史，与其自身侵暴也存在张力。"},{id:"daozhi-guide-02-04",text:"何故不谓子为盗丘，而乃谓我为盗跖？",guide:"反问社会名号是否因传统、权位而区别对待相似行为。",note:"揭露双重标准，不等于自己的侵害可以免责。"},{id:"daozhi-guide-02-05",text:"上无以为身，下无以为人。",guide:"盗跖以孔子与子路的遭遇，质疑教化的实际效果。",note:"发生不幸、教化造成不幸与教化全部无效，是不同结论。"},{id:"daozhi-guide-02-06",text:"离名轻死，不念本养寿命者也。",guide:"以情性与寿命重评社会尊奉的贤士，突出名声和生命代价的冲突。",note:"人物动机与所守价值没有因此得到完整否定。"},{id:"daozhi-guide-02-07",text:"目欲视色，耳欲听声，口欲察味，志气欲盈。",guide:"实际人情与欲求被提出为评价生活的内容。",note:"尚未说明欲求分寸、他人利益与长远照料如何协调。"},{id:"daozhi-guide-02-08",text:"操有时之具，而托于无穷之间。",guide:"有限身体与无穷天地形成对照，反省为外在目标无限推迟自身生活。",note:"生命短促不推出所有眼前欲望都应实行。"},{id:"daozhi-guide-02-09",text:"说其志意、养其寿命……全真。",guide:"盗跖以情性悦适、寿命养护检验所行之道。",note:"这一尺度也应反过来检验其侵暴与威胁，不能只用于批评他人。"},{id:"daozhi-guide-02-10",text:"丘所谓无病而自灸也。",guide:"结尾回应开篇劝阻，孔子承认此行自取危险。",note:"劝说失败与惊惧败退，不等于逐项认可盗跖全部论说。"},{id:"daozhi-guide-03-01",text:"无行则不信，不信则不任，不任则不利。",guide:"子张先用信任、任用与收益说明为行的作用，随后又转向内心与秩序。",note:"不把子张预先写成完全不问名利的人。"},{id:"daozhi-guide-03-02",text:"若弃名利，反之于心……抱其天乎！",guide:"双方都提出不计外在名利的情况，却分别落在行与本然情性上。",note:"分歧不自动证明行必然反天，或抱天必然不需修养。"},{id:"daozhi-guide-03-03",text:"贵贱之分，在行之美恶。",guide:"子张拆开权势高低与行为价值，不能因天子身份便判其可贵。",note:"社会称誉的反应还不是对行为美恶的完整论证。"},{id:"daozhi-guide-03-04",text:"论则贱之，行则下之。",guide:"满苟得转向口头评价与实际依附的裂缝。",note:"受礼、任职与认可全部行为仍应分别检验。"},{id:"daozhi-guide-03-05",text:"成者为首，不成者为尾。",guide:"揭示成功、权势与现实承认的联系。",note:"现实奖励成功，不等于成功自动证明正当。"},{id:"daozhi-guide-03-06",text:"五纪六位，将何以为别乎？",guide:"子张把问题推进到共同生活的关系秩序，而不只谈个人美名。"},{id:"daozhi-guide-03-07",text:"子正为名，我正为利。名利之实，不顺于理，不监于道。",guide:"满苟得将趋名与趋利共同置于理与道的检验之下。",note:"对子张只为名的归类未必充分；但满苟得也没有把自己的利免于检验。"},{id:"daozhi-guide-03-08",text:"小人殉财，君子殉名。",guide:"不同目标可能同样取得支配地位，使人改情易性、舍弃根本。",note:"不抹平所有义利差别，也不把一切取得财物或认可都称为殉。"},{id:"daozhi-guide-03-09",text:"与时消息……执而圆机。",guide:"结合韵语，强调面对实际变化保留调整，不固化名号与姿态。",note:"不等于取消全部原则；疑难字句不强作唯一逐字译文。"},{id:"daozhi-guide-03-10",text:"正其言，必其行，故服其殃、离其患也。",guide:"言行一致还需检验所持内容及其进入处境的方式。",note:"机械贯彻不自动合宜，列举极端祸患也不证明忠信廉义全部有害。"},{id:"daozhi-guide-04-01",text:"长生安体乐意之道也。",guide:"无足把财富、归附与尊奉连接到养生，提出需要认真回应的实际好处。",note:"归附与尊重不自动保证关系可靠或心意安定。"},{id:"daozhi-guide-04-02",text:"不为苟为，不为苟不为。",guide:"求与辞都需要根据，不能预先把其中一端固定为高尚。"},{id:"daozhi-guide-04-03",text:"人之所欲也。",guide:"承认名誉、富贵之求也是实际欲求，但满足方式仍须辨认。",note:"欲求存在不是无限扩张的许可证。"},{id:"daozhi-guide-04-04",text:"不足故求之……有余故辞之。",guide:"以所需与分寸判断，不受贪廉名号逼迫。",note:"不以自称不足免除对取得方式与后果的检验。"},{id:"daozhi-guide-04-05",text:"不以美害生，不以事害己。",guide:"目标受到认可，也不能使生命与自身代价从判断中消失。",note:"不是取消所有责任、行动与必要投入。"},{id:"daozhi-guide-04-06",text:"为清名而苦体绝甘，约养以持生。",guide:"刻意压缩供养求清名，也可能使外在目标支配生活。",note:"不能扩大为一切节俭与节制都错误。"},{id:"daozhi-guide-04-07",text:"平为福，有余为害。",guide:"财富有用，不等于越多越好；适量与过量需要分开。",note:"不是赞美贫穷，也不是把一切储备都称作有害。"},{id:"daozhi-guide-04-08",text:"今富人有此六害，而汝不知。",guide:"以实际负担、失调、忧虑与防失检验财富能否安体乐意。",note:"不是每个富人必然具有六害；六害说明采用所供解读概括。"}];function s(o){return y.filter(t=>t.id.startsWith(`daozhi-${o}`))}function g(o){return m.filter(t=>t.id.startsWith(`daozhi-guide-${o}-`))}function u(o){const t=new Set;for(const r of s(o))for(const h of r.sentences)for(const n of h)typeof n!="string"&&n.glossary&&t.add(n.glossary);return l.filter(r=>t.has(r.id)&&Array.from(r.term).length<=5)}const x=s("01"),c=u("01"),q=g("01"),k=s("02"),f=u("02"),P=g("02"),j=s("03"),w=u("03"),_=g("03"),T=s("04"),S=u("04"),A=g("04");return(o,t)=>{const r=b("DaoReadingPrelude"),h=b("DaoTextReading"),n=b("DaoKeywordCards"),p=b("DaoLineGuide");return D(),V("div",null,[t[0]||(t[0]=i("h1",{id:"庄子·盗跖",tabindex:"-1"},[e("庄子·盗跖 "),i("a",{class:"header-anchor",href:"#庄子·盗跖","aria-label":'Permalink to "庄子·盗跖"'},"​")],-1)),a(r,{title:"先读四节：说理、情性与欲望的边界",summary:"《盗跖》以孔子往见盗跖的长篇对答开篇，随后转入子张与满苟得、无足与知和两组论辩，把名位、行义、情性与财富的取舍放在同一张秤上。",points:[{label:"劝说",text:"说理要成立，除了道理本身，还需要什么条件？"},{label:"情性",text:"「顺情性」是否能为一切行为提供依据？"},{label:"分寸",text:"欲求与财富之间，界线应当划在哪里？"}],hint:"盗跖的反驳锋利，却不必句句当作作者定论；阅读时留意谁说、对谁说、说到什么程度。"}),t[1]||(t[1]=i("h2",{id:"一、孔子往见·劝阻、求见与封侯方案",tabindex:"-1"},[e("一、孔子往见·劝阻、求见与封侯方案 "),i("a",{class:"header-anchor",href:"#一、孔子往见·劝阻、求见与封侯方案","aria-label":'Permalink to "一、孔子往见·劝阻、求见与封侯方案"'},"​")],-1)),t[2]||(t[2]=i("h3",{id:"原文",tabindex:"-1"},[e("原文 "),i("a",{class:"header-anchor",href:"#原文","aria-label":'Permalink to "原文"'},"​")],-1)),a(h,{sections:d(x),glossary:l,"default-mode":"classic","aria-label":"盗跖·firstSection 原文"},null,8,["sections"]),t[3]||(t[3]=i("h3",{id:"字词释义",tabindex:"-1"},[e("字词释义 "),i("a",{class:"header-anchor",href:"#字词释义","aria-label":'Permalink to "字词释义"'},"​")],-1)),a(n,{items:d(c)},null,8,["items"]),t[4]||(t[4]=i("h3",{id:"逐句导读",tabindex:"-1"},[e("逐句导读 "),i("a",{class:"header-anchor",href:"#逐句导读","aria-label":'Permalink to "逐句导读"'},"​")],-1)),a(p,{lines:d(q)},null,8,["lines"]),t[5]||(t[5]=z('<h3 id="深入解读" tabindex="-1">深入解读 <a class="header-anchor" href="#深入解读" aria-label="Permalink to &quot;深入解读&quot;">​</a></h3><h4 id="一、开篇先写暴行-雄辩不能替代行为判断" tabindex="-1">一、开篇先写暴行：雄辩不能替代行为判断 <a class="header-anchor" href="#一、开篇先写暴行-雄辩不能替代行为判断" aria-label="Permalink to &quot;一、开篇先写暴行：雄辩不能替代行为判断&quot;">​</a></h4><p>盗跖先被写为侵暴诸侯、侵入居室、掠取牲畜与妇女、不顾亲属祭祀，使各地防守、百姓受苦。后面又有残酷的饮食描写。</p><p>这些是论辩不可省略的背景。他并非只是一位隐者、异端思想者或敢言之士。</p><p>但也需要分开：</p><p><strong>他的批评是否有根据，与他的行为是否因此正当，是两个问题。</strong></p><p>开篇残暴不使后面所有论说自动失效；指出他人的矛盾，也不使自己的暴行得到免责。</p><h4 id="二、亲属教导-有责任不等于能保证结果" tabindex="-1">二、亲属教导：有责任不等于能保证结果 <a class="header-anchor" href="#二、亲属教导-有责任不等于能保证结果" aria-label="Permalink to &quot;二、亲属教导：有责任不等于能保证结果&quot;">​</a></h4><blockquote><p>为人父者，必能诏其子；为人兄者，必能教其弟。</p></blockquote><p>孔子把教导责任与教化结果紧密相连，并以盗跖未改责问柳下季。</p><p>柳下季则提出：</p><blockquote><p>若子不听父之诏，弟不受兄之教……将奈之何哉？</p></blockquote><table tabindex="0"><thead><tr><th>层面</th><th>需要区分的内容</th></tr></thead><tbody><tr><td>责任</td><td>父兄是否应当关心、教导</td></tr><tr><td>能力</td><td>是否能使子弟必然听从</td></tr><tr><td>结果</td><td>对方是否实际改变</td></tr></tbody></table><p>对方未改，不能单独证明教导者没有尽责。</p><p>柳下季也没有说从此不必关心子弟，或盗跖的行为无需回应；他主要反对责任与保证结果被直接等同。</p><h4 id="三、听者的条件-辩才也可能用于保护既有行为" tabindex="-1">三、听者的条件：辩才也可能用于保护既有行为 <a class="header-anchor" href="#三、听者的条件-辩才也可能用于保护既有行为" aria-label="Permalink to &quot;三、听者的条件：辩才也可能用于保护既有行为&quot;">​</a></h4><blockquote><p>心如涌泉，意如飘风。<br> 强足以距敌，辩足以饰非。</p></blockquote><p>柳下季指出强力、辩才、心意变化，以及顺喜逆怒、轻易辱人的回应方式。</p><p>劝说效果不只取决于劝说者有没有道理，还取决于听者是否愿意听，如何使用自己的能力。</p><p>“辩足以饰非”尤其表明：辩才不自动等于愿意反省。</p><p>不过，这是柳下季对弟弟的评价。后面的反驳仍须逐项分析，不能据此预判一切只是狡辩。</p><h4 id="四、孔子不听-前往发生在已有警告之后" tabindex="-1">四、孔子不听：前往发生在已有警告之后 <a class="header-anchor" href="#四、孔子不听-前往发生在已有警告之后" aria-label="Permalink to &quot;四、孔子不听：前往发生在已有警告之后&quot;">​</a></h4><p>孔子知道对方可能不受教，也知道此行有危险，仍然前往。</p><p>可以说行动表现了劝说的坚持，但不能凭此补齐全部动机：是否自信能够教化、不能放弃责任、低估风险，原文没有逐项说明。</p><p>结尾“无病而自灸”将回过头来评价这次前往，使开篇劝阻成为故事的重要条件。</p><h4 id="五、称誉与私人关系-先争取对话入口" tabindex="-1">五、称誉与私人关系：先争取对话入口 <a class="header-anchor" href="#五、称誉与私人关系-先争取对话入口" aria-label="Permalink to &quot;五、称誉与私人关系：先争取对话入口&quot;">​</a></h4><blockquote><p>闻将军高义。</p></blockquote><p>孔子没有从直接责斥开始，而以尊称、称誉求得会面。这与开篇暴行形成反差，但不能直接证明他认可盗跖全部行为，也不能证明其礼貌全是虚伪。</p><p>第一次通报遭辱斥，孔子再以与柳下季的交情请求入见。</p><p>会面先依赖关系与许可，并非论证一经提出便自然发生。</p><h4 id="六、对话不对等-礼与威势的对照" tabindex="-1">六、对话不对等：礼与威势的对照 <a class="header-anchor" href="#六、对话不对等-礼与威势的对照" aria-label="Permalink to &quot;六、对话不对等：礼与威势的对照&quot;">​</a></h4><table tabindex="0"><thead><tr><th>孔子</th><th>盗跖</th></tr></thead><tbody><tr><td>趋进、退避、再拜</td><td>展足、按剑、怒视</td></tr><tr><td>求得交谈</td><td>控制交谈条件</td></tr><tr><td>希望改变对方行为</td><td>要求话语顺从己意</td></tr></tbody></table><blockquote><p>若所言顺吾意则生，逆吾心则死。</p></blockquote><p>劝说需要触动原有判断，盗跖却以生命威胁排斥逆耳之言。这使目标与条件一开始就冲突。</p><p>孔子的称誉和利益安排，应放在受威胁的场景中理解；后面的败退，也不能仅按抽象论证胜负判断。</p><h4 id="七、第一次辱斥-反击方向已经显现" tabindex="-1">七、第一次辱斥：反击方向已经显现 <a class="header-anchor" href="#七、第一次辱斥-反击方向已经显现" aria-label="Permalink to &quot;七、第一次辱斥：反击方向已经显现&quot;">​</a></h4><p>盗跖在正式听到方案之前，便指控孔子作言造语、尊奉文武、不亲耕织、制造是非、以孝弟话语谋封侯富贵。</p><p>这是带有强烈敌意的指控，不是已经得到证明的中性描述。</p><p>但论题与后续相连：孔子随后提出封侯方案，盗跖便从“规我以利”继续反击，质疑教化与名位安排。</p><h4 id="八、三德-承认能力-再转向政治身份" tabindex="-1">八、三德：承认能力，再转向政治身份 <a class="header-anchor" href="#八、三德-承认能力-再转向政治身份" aria-label="Permalink to &quot;八、三德：承认能力，再转向政治身份&quot;">​</a></h4><table tabindex="0"><thead><tr><th>三德</th><th>内容</th><th>劝说作用</th></tr></thead><tbody><tr><td>上德</td><td>长大美好，众人悦之</td><td>承认身体条件与吸引力</td></tr><tr><td>中德</td><td>才智通达，能辨诸物</td><td>承认才智与辨析能力</td></tr><tr><td>下德</td><td>勇悍果敢，聚众率兵</td><td>承认勇力与组织能力</td></tr></tbody></table><p>此处“德”不限于现代意义的道德善行。</p><p>孔子不先否定对方全部能力，而说这些条件可以转向君位。其发言具有劝说策略的作用，并未完整论证有这些能力就必然适合为君。</p><h4 id="九、盗首到诸侯-方案同时改变行为与名号" tabindex="-1">九、盗首到诸侯：方案同时改变行为与名号 <a class="header-anchor" href="#九、盗首到诸侯-方案同时改变行为与名号" aria-label="Permalink to &quot;九、盗首到诸侯：方案同时改变行为与名号&quot;">​</a></h4><p>孔子认为“盗跖”之名与所赞条件不相称，随后提出尊为诸侯。</p><p>这不只是停止暴行，也涉及从盗首到受认可诸侯的身份转换。</p><table tabindex="0"><thead><tr><th>层面</th><th>安排</th><th>对开篇的回应</th></tr></thead><tbody><tr><td>物质与人口</td><td>建城、立邑</td><td>提供另一种资源基础</td></tr><tr><td>政治身份</td><td>尊为诸侯、与天下更始</td><td>改变名号与关系</td></tr><tr><td>军事行为</td><td>罢兵休卒</td><td>回应横行侵暴</td></tr><tr><td>亲属祭祀</td><td>收养昆弟、共祭先祖</td><td>回应忘亲、不祭祖</td></tr></tbody></table><p>方案不只是送奖励，而是尝试用政治安排重组行为；但它确实以土地、人口与名位吸引，也未证明能够实行。</p><h4 id="十、天下之愿-公共认可不保证共同尺度" tabindex="-1">十、天下之愿：公共认可不保证共同尺度 <a class="header-anchor" href="#十、天下之愿-公共认可不保证共同尺度" aria-label="Permalink to &quot;十、天下之愿：公共认可不保证共同尺度&quot;">​</a></h4><blockquote><p>此圣人才士之行，而天下之愿也。</p></blockquote><p>孔子用理想人格与公共期待说明方案价值。开篇“万民苦之”与此相接：盗跖的能力与利益，被尝试转向他人的安宁。</p><p>但“天下之愿”仍是发言中的表述，不是另行展示的全体意见调查，也不能使受劝者必然接受同一尺度。</p><h3 id="本节脉络" tabindex="-1">本节脉络 <a class="header-anchor" href="#本节脉络" aria-label="Permalink to &quot;本节脉络&quot;">​</a></h3><p><strong>孔子提出教导责任</strong><br> → <strong>柳下季指出责任不能保证听从</strong><br> → <strong>孔子仍往，在敌意与威胁中求见</strong><br> → <strong>先称誉条件，再提出身份与秩序转换</strong><br> → <strong>以圣贤之行、天下之愿支持方案</strong><br> → <strong>盗跖将称誉与利益重新解释为操控。</strong></p><p>前后的论辩应连续理解，不拆成彼此无关的观点。</p><h2 id="二、盗跖反击·名位、情性与有限生命" tabindex="-1">二、盗跖反击·名位、情性与有限生命 <a class="header-anchor" href="#二、盗跖反击·名位、情性与有限生命" aria-label="Permalink to &quot;二、盗跖反击·名位、情性与有限生命&quot;">​</a></h2><h3 id="原文-1" tabindex="-1">原文 <a class="header-anchor" href="#原文-1" aria-label="Permalink to &quot;原文&quot;">​</a></h3>',57)),a(h,{sections:d(k),glossary:l,"default-mode":"classic","aria-label":"盗跖·secondSection 原文"},null,8,["sections"]),t[6]||(t[6]=i("h3",{id:"字词释义-1",tabindex:"-1"},[e("字词释义 "),i("a",{class:"header-anchor",href:"#字词释义-1","aria-label":'Permalink to "字词释义"'},"​")],-1)),a(n,{items:d(f)},null,8,["items"]),t[7]||(t[7]=i("h3",{id:"逐句导读-1",tabindex:"-1"},[e("逐句导读 "),i("a",{class:"header-anchor",href:"#逐句导读-1","aria-label":'Permalink to "逐句导读"'},"​")],-1)),a(p,{lines:d(P)},null,8,["lines"]),t[8]||(t[8]=z('<h3 id="深入解读-1" tabindex="-1">深入解读 <a class="header-anchor" href="#深入解读-1" aria-label="Permalink to &quot;深入解读&quot;">​</a></h3><h4 id="一、反击从眼前方案开始" tabindex="-1">一、反击从眼前方案开始 <a class="header-anchor" href="#一、反击从眼前方案开始" aria-label="Permalink to &quot;一、反击从眼前方案开始&quot;">​</a></h4><p>孔子称誉禀赋、提出城邑与诸侯身份，盗跖首先回应：</p><ul><li>自身条件，不需对方称赞才知道；</li><li>城邑利益，是对方试图安排自己的方式。</li></ul><p>称誉原本用于接近，利益原本用于促成改变，却被解释为评价依赖与收纳控制。因此，这不是突然另起的泛泛富贵批评。</p><h4 id="二、拒绝称誉-不让对方成为价值确认者" tabindex="-1">二、拒绝称誉：不让对方成为价值确认者 <a class="header-anchor" href="#二、拒绝称誉-不让对方成为价值确认者" aria-label="Permalink to &quot;二、拒绝称誉：不让对方成为价值确认者&quot;">​</a></h4><blockquote><p>丘虽不吾誉，吾独不自知邪？</p></blockquote><p>盗跖将容貌等归于父母遗德，拒绝依孔子的称誉确认自身。</p><p>“好面誉人者，亦好背而毁之”表达对称誉者的怀疑，但不证明所有赞美都伴随后来的毁谤。</p><p>而其“自知”主要指禀赋，不等于已经充分反省侵暴行为。</p><h4 id="三、恒民畜我-利益与关系被一起拒绝" tabindex="-1">三、恒民畜我：利益与关系被一起拒绝 <a class="header-anchor" href="#三、恒民畜我-利益与关系被一起拒绝" aria-label="Permalink to &quot;三、恒民畜我：利益与关系被一起拒绝&quot;">​</a></h4><blockquote><p>是欲规我以利而恒民畜我也。</p></blockquote><p>在他看来，受封不是单纯改善待遇，而是进入孔子及诸侯所设定的秩序。</p><p>这可以与《让王》“贵重不等于应受”对读，但不能把盗跖全部美化为平等、开放的主体独立。他轻蔑恒民，以不受规谏自傲。</p><p><strong>不受控制，与愿意接受合理检验，并不是一回事。</strong></p><h4 id="四、大利不保证长久-反问尚非完整因果证明" tabindex="-1">四、大利不保证长久：反问尚非完整因果证明 <a class="header-anchor" href="#四、大利不保证长久-反问尚非完整因果证明" aria-label="Permalink to &quot;四、大利不保证长久：反问尚非完整因果证明&quot;">​</a></h4><blockquote><p>城之大者，莫大乎天下矣。</p></blockquote><p>盗跖把城邑放大到天下，以尧舜、汤武后世的结局动摇权位利益的可靠性。</p><p>但“非以其利大故邪”没有完整证明利益越大就必然败亡，也未证明所列结局只有这一原因。</p><p>其作用是质疑利诱的安稳、长久，不应直接抽成确定的历史因果规律。</p><h4 id="五、重述古史-从不相害到强凌弱" tabindex="-1">五、重述古史：从不相害到强凌弱 <a class="header-anchor" href="#五、重述古史-从不相害到强凌弱" aria-label="Permalink to &quot;五、重述古史：从不相害到强凌弱&quot;">​</a></h4><p>盗跖描绘巢居、取暖、耕织、与麋鹿共处的生活，并将神农之世“不相害”称为至德。</p><p>随后出现战争、群臣、放逐与杀伐，归结为强凌弱、众暴寡。</p><p>他将受尊奉的政治传统重述为自然生活转向争夺暴力的过程。这是评价性古史，不是中性年表；“知母不知父”也不能直接用于建立完整制度史。</p><p>更重要的是：<strong>其所赞的不相害，与自身侵暴存在明显张力。</strong></p><h4 id="六、盗丘之问-名称与行为是否一致" tabindex="-1">六、盗丘之问：名称与行为是否一致 <a class="header-anchor" href="#六、盗丘之问-名称与行为是否一致" aria-label="Permalink to &quot;六、盗丘之问：名称与行为是否一致&quot;">​</a></h4><blockquote><p>天下何故不谓子为盗丘，而乃谓我为盗跖？</p></blockquote><p>此问承接孔子改变名号的安排，质疑传统、权位与美名是否使相似的夺取行为获得不同待遇。</p><p>可以由此反省双重标准，但还须区分：</p><ul><li>社会评价是否一致；</li><li>自己的行为是否因此不再有害。</li></ul><p>别人有过，不能成为自己的自动免责理由。</p><h4 id="七、子路与孔子的遭遇-教化结果需要因果辨认" tabindex="-1">七、子路与孔子的遭遇：教化结果需要因果辨认 <a class="header-anchor" href="#七、子路与孔子的遭遇-教化结果需要因果辨认" aria-label="Permalink to &quot;七、子路与孔子的遭遇：教化结果需要因果辨认&quot;">​</a></h4><p>盗跖由传统转向孔子的实际教导，以子路惨死与孔子屡遭困厄，质疑其道能否为己、为人。</p><table tabindex="0"><thead><tr><th>论述步骤</th><th>需要检验</th></tr></thead><tbody><tr><td>受教后发生不幸</td><td>不幸实际是什么</td></tr><tr><td>教化造成不幸</td><td>因果是否得到证明</td></tr><tr><td>教化因此不足贵</td><td>是否足以否定全部内容</td></tr></tbody></table><p>盗跖将几层紧密连接，原文却没有提供完整的因果证明。</p><p>子路相关说法，应首先按本篇人物的论辩材料理解，不直接取代其他典籍中的记载。</p><h4 id="八、帝王、贤士、忠臣-社会尊高与生命代价" tabindex="-1">八、帝王、贤士、忠臣：社会尊高与生命代价 <a class="header-anchor" href="#八、帝王、贤士、忠臣-社会尊高与生命代价" aria-label="Permalink to &quot;八、帝王、贤士、忠臣：社会尊高与生命代价&quot;">​</a></h4><table tabindex="0"><thead><tr><th>所列类别</th><th>社会尊奉的方向</th><th>盗跖的重评</th></tr></thead><tbody><tr><td>帝王、圣王</td><td>功业与政治传统</td><td>利惑其真，强反情性</td></tr><tr><td>贤士</td><td>廉、忠、信等操守</td><td>系于名而轻死</td></tr><tr><td>忠臣</td><td>忠于君主</td><td>遭杀，未全自身</td></tr></tbody></table><p>三类例子共同检验社会赞誉是否遮蔽情性与寿命代价。</p><p>但“为天下笑”“皆不足贵”都是盗跖的强烈评价，不能当作共同意见，也不能仅凭死亡证明所守毫无价值。</p><h4 id="九、伯夷叔齐-两篇的尺度冲突" tabindex="-1">九、伯夷叔齐：两篇的尺度冲突 <a class="header-anchor" href="#九、伯夷叔齐-两篇的尺度冲突" aria-label="Permalink to &quot;九、伯夷叔齐：两篇的尺度冲突&quot;">​</a></h4><table tabindex="0"><thead><tr><th>《让王》结尾</th><th>此处盗跖发言</th></tr></thead><tbody><tr><td>此二士之节也</td><td>离名轻死，不念本养寿命</td></tr><tr><td>肯定不苟取、不苟合</td><td>强调养寿损失</td></tr><tr><td>独乐其志</td><td>怀疑为名所累</td></tr></tbody></table><p>不能简单认定《盗跖》替《让王》作了最后纠正。这里是人物发言，两篇也有不同叙事结构。</p><p>对读更适合留下两问：肯定操守时，怎样看见生命代价？重视生命时，是否会抹去所守价值？</p><h4 id="十、人情进入判断-尚未完成欲求分寸论" tabindex="-1">十、人情进入判断：尚未完成欲求分寸论 <a class="header-anchor" href="#十、人情进入判断-尚未完成欲求分寸论" aria-label="Permalink to &quot;十、人情进入判断：尚未完成欲求分寸论&quot;">​</a></h4><blockquote><p>目欲视色，耳欲听声，口欲察味，志气欲盈。</p></blockquote><p>盗跖提出实际欲求，反对只按名号、功业与德目评价生活。</p><p>但此处尚未说明：</p><ul><li>欲求之间如何协调；</li><li>满足是否侵害他人；</li><li>过度欲求怎样限制；</li><li>当前悦适与未来寿命怎样相应。</li></ul><p>人情值得进入判断，不等于所有欲求应无限满足。</p><h4 id="十一、有限生命-不能无限推迟生活-也不取消照料" tabindex="-1">十一、有限生命：不能无限推迟生活，也不取消照料 <a class="header-anchor" href="#十一、有限生命-不能无限推迟生活-也不取消照料" aria-label="Permalink to &quot;十一、有限生命：不能无限推迟生活，也不取消照料&quot;">​</a></h4><p>寿命数字与“一月不过四五日”集中强调欢乐有限，不作为普遍生活统计。</p><blockquote><p>操有时之具，而托于无穷之间。</p></blockquote><p>身体有限、天地无穷，骐骥过隙使短促更鲜明。这段反省为外在目标不断延后自身生活。</p><p>但寿命短促不自动推出立即满足一切。长远照料、必要约束与对他人的责任仍需辨认。</p><h4 id="十二、悦志、养寿、全真-尺度也应反过来检验说话者" tabindex="-1">十二、悦志、养寿、全真：尺度也应反过来检验说话者 <a class="header-anchor" href="#十二、悦志、养寿、全真-尺度也应反过来检验说话者" aria-label="Permalink to &quot;十二、悦志、养寿、全真：尺度也应反过来检验说话者&quot;">​</a></h4><blockquote><p>不能说其志意、养其寿命者，皆非通道者也。<br> 非可以全真也。</p></blockquote><p>盗跖用情性悦适与寿命养护检验所行之道，“全真”不仅是诚实说话。</p><p>但其侵害他人、以死亡威胁孔子，如何符合不相害与全真？本段没有给出回答。</p><p><strong>提出值得思考的尺度，不等于已经依此生活。</strong></p><h4 id="十三、孔子败退-挫败不等于逐项认同" tabindex="-1">十三、孔子败退：挫败不等于逐项认同 <a class="header-anchor" href="#十三、孔子败退-挫败不等于逐项认同" aria-label="Permalink to &quot;十三、孔子败退：挫败不等于逐项认同&quot;">​</a></h4><p>孔子执辔失措、目光恍惚、面如死灰、不能出气，表现强烈惊惧。</p><table tabindex="0"><thead><tr><th>已写出的结果</th><th>不能自动推出</th></tr></thead><tbody><tr><td>劝说失败</td><td>孔子所守全部被推翻</td></tr><tr><td>惊惧败退</td><td>盗跖每项论证都成立</td></tr><tr><td>未作反驳</td><td>已认可全部主张</td></tr></tbody></table><p>结局既有论辩挫败，也有暴力压迫，不能只保留其中一层。</p><h4 id="十四、无病而自灸-回应开篇的劝阻" tabindex="-1">十四、无病而自灸：回应开篇的劝阻 <a class="header-anchor" href="#十四、无病而自灸-回应开篇的劝阻" aria-label="Permalink to &quot;十四、无病而自灸：回应开篇的劝阻&quot;">​</a></h4><p>柳下季开篇劝“必无往”，孔子结尾承认自取危险，以触弄猛虎形容此行。</p><p>故事形成闭合：</p><p><strong>劝阻</strong> → <strong>不听而往</strong> → <strong>遭威胁与反击</strong> → <strong>承认贸然冒险。</strong></p><p>这不是孔子逐项承认对方思想与行为都正确，而是提醒劝说不能只从自己有理由出发，还要看对方、场景与实际可能。</p><h2 id="一至二段·阶段性脉络" tabindex="-1">一至二段·阶段性脉络 <a class="header-anchor" href="#一至二段·阶段性脉络" aria-label="Permalink to &quot;一至二段·阶段性脉络&quot;">​</a></h2><h3 id="一、双方提出什么-又尚未完成什么" tabindex="-1">一、双方提出什么，又尚未完成什么 <a class="header-anchor" href="#一、双方提出什么-又尚未完成什么" aria-label="Permalink to &quot;一、双方提出什么，又尚未完成什么&quot;">​</a></h3><table tabindex="0"><thead><tr><th>人物</th><th>提出的方向</th><th>未完成的问题</th></tr></thead><tbody><tr><td>孔子</td><td>用称誉、封侯及秩序安排促成改变</td><td>未使盗跖接受共同评价尺度，也未证明方案实际可行</td></tr><tr><td>盗跖</td><td>用生命、情性批评名位与教化</td><td>未说明自己的侵暴如何符合不相害、养寿与全真</td></tr></tbody></table><p>不能整理为孔子代表全部虚伪、盗跖代表全部真理；也不能因盗跖残暴，就拒绝分析其提出的矛盾。</p><p>故事使教化自信受挫，同时要求读者辨认说话者与所说之理可能不一致。</p><h3 id="二、与《让王》的初步对读" tabindex="-1">二、与《让王》的初步对读 <a class="header-anchor" href="#二、与《让王》的初步对读" aria-label="Permalink to &quot;二、与《让王》的初步对读&quot;">​</a></h3><table tabindex="0"><thead><tr><th>本文内容</th><th>《让王》参照</th><th>联系与区别</th></tr></thead><tbody><tr><td>用名位与待遇促成改变</td><td>屠羊说辞赏</td><td>外在贵重不保证受者认可给予根据</td></tr><tr><td>给予者设想更好生活</td><td>善卷不受天下</td><td>对方认为改善，不等于符合受者所需</td></tr><tr><td>三德与为君条件</td><td>可以托天下的论说</td><td>都谈为君，但强调的条件不同</td></tr><tr><td>称誉、利益与收纳</td><td>列子辞粟等辞受故事</td><td>应检验给予方式；盗跖还带有轻蔑与暴力背景</td></tr><tr><td>伯夷叔齐的生命结局</td><td>二士之节</td><td>操守与养寿的尺度可能冲突</td></tr><tr><td>道理与实际状态</td><td>公子牟未能自胜</td><td>可比较认识与落实，不直接等同两则处境</td></tr></tbody></table><p>盗跖的暴行与威胁是本篇特有背景，不能因此将其直接归入《让王》的辞让者之列。</p><h3 id="三、现实阅读中的辨析" tabindex="-1">三、现实阅读中的辨析 <a class="header-anchor" href="#三、现实阅读中的辨析" aria-label="Permalink to &quot;三、现实阅读中的辨析&quot;">​</a></h3><p>以下属于现代引申，不是原文制定的固定行动规则。</p><ul><li>**教导责任不等于控制结果。**可以检验是否尽责，也应承认他人有自己的回应。</li><li>**称誉与利益不保证建立信任。**提出改善方案时，还需了解对方如何理解身份、关系与代价。</li><li>**有理由不等于适合直接接触。**面对明确暴力威胁，安全条件不能被抽象说理代替。</li><li>**批评与免责应分开。**指出他人的双重标准，不使自己的侵害变得正当。</li><li>**不幸与因果应分开。**结果失败、遭遇灾难，并不自动证明全部教导错误。</li><li>**生命代价值得看见，原则价值也须辨认。**不以死亡设置道德门槛，也不只凭死亡否定全部操守。</li><li>**尺度应双向使用。**不能只用不相害、全真或养寿批评别人，而回避自己的行为。</li></ul><h3 id="四、核心句对照" tabindex="-1">四、核心句对照 <a class="header-anchor" href="#四、核心句对照" aria-label="Permalink to &quot;四、核心句对照&quot;">​</a></h3><table tabindex="0"><thead><tr><th>核心句</th><th>阅读重点</th><th>应避免的误读</th></tr></thead><tbody><tr><td>万民苦之</td><td>暴行与受害者是叙事起点</td><td>雄辩使暴行自动正当</td></tr><tr><td>必能诏其子，必能教其弟</td><td>教导责任与结果被相连</td><td>未改便证明父兄失责</td></tr><tr><td>弟不受兄之教，将奈之何</td><td>听者回应限制教化</td><td>无需再关心或教导</td></tr><tr><td>闻将军高义</td><td>称誉用于打开对话</td><td>直接认可全部行为</td></tr><tr><td>顺吾意则生，逆吾心则死</td><td>暴力控制对话条件</td><td>只是平等的逻辑论辩</td></tr><tr><td>今将军兼此三者</td><td>承认禀赋、能力，转向身份</td><td>三德全是道德善行</td></tr><tr><td>尊将军为诸侯，与天下更始</td><td>利益与秩序共同促成改变</td><td>已证明方案可行</td></tr><tr><td>丘虽不吾誉，吾独不自知邪</td><td>拒绝依赖对方确认禀赋</td><td>已充分反省全部行为</td></tr><tr><td>规我以利而恒民畜我</td><td>给予也被理解为收纳</td><td>一切给予都必然控制</td></tr><tr><td>无有相害之心</td><td>所赞理想可反检验自身</td><td>盗跖已实践不相害</td></tr><tr><td>何故不谓子为盗丘</td><td>名号与行为是否一致</td><td>别人有过便可免责</td></tr><tr><td>上无以为身，下无以为人</td><td>以遭遇质疑教化效果</td><td>不幸即证明全部错误</td></tr><tr><td>离名轻死，不念本养寿命</td><td>社会尊高与生命代价</td><td>所守价值已被全部否定</td></tr><tr><td>说其志意，养其寿命</td><td>实际情性与有限生命</td><td>欲求必须无限满足</td></tr><tr><td>非可以全真也</td><td>用情性与生命检验所行</td><td>说话者已践行该尺度</td></tr><tr><td>无病而自灸</td><td>前往失败与自取危险</td><td>败退证明对方一切正确</td></tr></tbody></table><h2 id="三、子张与满苟得·行义、名利与情性" tabindex="-1">三、子张与满苟得·行义、名利与情性 <a class="header-anchor" href="#三、子张与满苟得·行义、名利与情性" aria-label="Permalink to &quot;三、子张与满苟得·行义、名利与情性&quot;">​</a></h2><h3 id="原文-2" tabindex="-1">原文 <a class="header-anchor" href="#原文-2" aria-label="Permalink to &quot;原文&quot;">​</a></h3>',84)),a(h,{sections:d(j),glossary:l,"default-mode":"classic","aria-label":"盗跖·thirdSection 原文"},null,8,["sections"]),t[9]||(t[9]=i("h3",{id:"字词释义-2",tabindex:"-1"},[e("字词释义 "),i("a",{class:"header-anchor",href:"#字词释义-2","aria-label":'Permalink to "字词释义"'},"​")],-1)),a(n,{items:d(w)},null,8,["items"]),t[10]||(t[10]=i("h3",{id:"逐句导读-2",tabindex:"-1"},[e("逐句导读 "),i("a",{class:"header-anchor",href:"#逐句导读-2","aria-label":'Permalink to "逐句导读"'},"​")],-1)),a(p,{lines:d(_)},null,8,["lines"]),t[11]||(t[11]=z('<h3 id="深入解读-2" tabindex="-1">深入解读 <a class="header-anchor" href="#深入解读-2" aria-label="Permalink to &quot;深入解读&quot;">​</a></h3><h4 id="一、子张也以名利劝行-不先设定纯粹的义利对立" tabindex="-1">一、子张也以名利劝行：不先设定纯粹的义利对立 <a class="header-anchor" href="#一、子张也以名利劝行-不先设定纯粹的义利对立" aria-label="Permalink to &quot;一、子张也以名利劝行：不先设定纯粹的义利对立&quot;">​</a></h4><blockquote><p>无行则不信，不信则不任，不任则不利。</p></blockquote><p>子张以信任、任用与收益支持行义，并非完全不计名利。</p><p>但随后又问：若不计名利、反观内心，是否仍应为行？这说明他的立场不止于收益，也包含行的内在价值。</p><p>满苟得先用“无耻者富，多信者显”动摇收益论证，再将内在落点转向“抱其天”。</p><p>“多信者显”的信有疑难，不直接译为诚信者显达。此时的分歧也尚未证明行必反天，或抱天无需修养。</p><h4 id="二、行为贵贱-职位不能包办价值" tabindex="-1">二、行为贵贱：职位不能包办价值 <a class="header-anchor" href="#二、行为贵贱-职位不能包办价值" aria-label="Permalink to &quot;二、行为贵贱：职位不能包办价值&quot;">​</a></h4><blockquote><p>势为天子，未必贵也；穷为匹夫，未必贱也。</p></blockquote><p>子张以桀纣与孔墨作对照，说明地位高低与行为美恶不是同一个问题。</p><p>但他主要举出人们对称誉、贬斥的反应，证明社会中存在不同于权势的尺度；行为美恶如何判定，仍未完整展开。</p><h4 id="三、口头贬斥-行动依附-评价需要进入实践" tabindex="-1">三、口头贬斥，行动依附：评价需要进入实践 <a class="header-anchor" href="#三、口头贬斥-行动依附-评价需要进入实践" aria-label="Permalink to &quot;三、口头贬斥，行动依附：评价需要进入实践&quot;">​</a></h4><blockquote><p>小盗者拘，大盗者为诸侯。<br> 论则贱之，行则下之。</p></blockquote><p>满苟得不直接否认行为评价，而转向所说与所做是否相应：口头贬斥某类行为，行动却依附实施该行为的权势者，是否形成冲突？</p><p>相关古史须先作为论辩材料理解。同时仍应区分接受礼物、任职与全面认可对方行为。</p><p>“成者为首，不成者为尾”揭示现实承认可能随权势转移，不等于成功使一切行为正当。</p><h4 id="四、人伦秩序-子张的主张不只关乎美名" tabindex="-1">四、人伦秩序：子张的主张不只关乎美名 <a class="header-anchor" href="#四、人伦秩序-子张的主张不只关乎美名" aria-label="Permalink to &quot;四、人伦秩序：子张的主张不只关乎美名&quot;">​</a></h4><blockquote><p>疏戚无伦，贵贱无义，长幼无序。</p></blockquote><p>子张进一步问共同生活如何辨明关系、维持秩序。</p><p>满苟得按疏戚、贵贱、长幼逐项举圣王反例，质疑秩序典范是否符合所代表的规范。</p><p>反驳具有对应结构，但典范违反规范，不自动证明全部关系规范都无价值。</p><p><strong>典范名称不能代替实际检验，揭露典范矛盾也不能包办秩序问题的回答。</strong></p><h4 id="五、共同检验名利-不再只是你错我对" tabindex="-1">五、共同检验名利：不再只是你错我对 <a class="header-anchor" href="#五、共同检验名利-不再只是你错我对" aria-label="Permalink to &quot;五、共同检验名利：不再只是你错我对&quot;">​</a></h4><blockquote><p>子正为名，我正为利。名利之实，不顺于理，不监于道。</p></blockquote><p>将子张归为只求名，未必概括其全部主张；子张还谈内在价值与共同秩序。</p><p>但此处重要的转折是满苟得把自身趋利也纳入检验，而不只替求利辩护。</p><blockquote><p>小人殉财，君子殉名。</p></blockquote><p>比较的是“殉”的结构：不同目标，都可能以自身为代价，改变情性、舍弃根本。</p><p>必要谋生不必是殉财，行为受到认可不必是殉名。关键是目标是否取得压倒性的支配地位。</p><h4 id="六、所为与所不为-不让目标吞没根本" tabindex="-1">六、所为与所不为：不让目标吞没根本 <a class="header-anchor" href="#六、所为与所不为-不让目标吞没根本" aria-label="Permalink to &quot;六、所为与所不为：不让目标吞没根本&quot;">​</a></h4><blockquote><p>弃其所为而殉其所不为。</p></blockquote><p>结合天、情、性，可以联系舍弃本应照料的情性生命，追逐不应居于最高位置的目标理解。</p><p>但原文没有逐项列出所为与所不为，不能径译为凡非满足欲望的活动都不应做。</p><p>本段检验的是目标与自身的关系，而非提供一张固定活动清单。</p><h4 id="七、后半韵语-不固化身份-也不取消判断" tabindex="-1">七、后半韵语：不固化身份，也不取消判断 <a class="header-anchor" href="#七、后半韵语-不固化身份-也不取消判断" aria-label="Permalink to &quot;七、后半韵语：不固化身份，也不取消判断&quot;">​</a></h4><p>“无为小人”与“无为君子”并列，既警惕殉财，也警惕君子之名成为束缚。</p><table tabindex="0"><thead><tr><th>韵语方向</th><th>可把握的重点</th></tr></thead><tbody><tr><td>枉直、是非与圆机</td><td>不凝固自己的判断</td></tr><tr><td>与时消息、与道徘徊</td><td>面对变化保留调整</td></tr><tr><td>无成而义、无赴而富、无殉而成</td><td>不使义、富与成就吞没自身</td></tr></tbody></table><p>这些是结合上下文的整体解释，不是每个字都已得到唯一训释。</p><p>不被标签与姿态支配，不等于所有原则与责任都取消。</p><h4 id="八、德目之祸-一致还须检验内容与处境" tabindex="-1">八、德目之祸：一致还须检验内容与处境 <a class="header-anchor" href="#八、德目之祸-一致还须检验内容与处境" aria-label="Permalink to &quot;八、德目之祸：一致还须检验内容与处境&quot;">​</a></h4><table tabindex="0"><thead><tr><th>德目</th><th>所举材料</th><th>强调的代价</th></tr></thead><tbody><tr><td>忠</td><td>比干、子胥</td><td>身体与生命遭害</td></tr><tr><td>信</td><td>直躬、尾生</td><td>关系损伤或死亡</td></tr><tr><td>廉</td><td>鲍子、申子</td><td>极端坚持的损害</td></tr><tr><td>义</td><td>孔子、匡子相关说法</td><td>亲属关系失当</td></tr></tbody></table><p>列举极端后果，不等于忠信廉义必然有害。部分事迹也简约、有疑义，不补成确定传记。</p><blockquote><p>正其言，必其行，故服其殃、离其患也。</p></blockquote><p>前面警惕言行冲突，结尾又警惕机械贯彻，二者可以分别理解：</p><ul><li>所说与所做需要一致性检验；</li><li>一致本身不能证明所持内容合宜。</li></ul><p><strong>不仅问是否贯彻，还要问贯彻什么、怎样进入实际处境。</strong></p><h3 id="本节脉络-1" tabindex="-1">本节脉络 <a class="header-anchor" href="#本节脉络-1" aria-label="Permalink to &quot;本节脉络&quot;">​</a></h3><p><strong>行能带来收益</strong><br> → <strong>名利未必由行义取得</strong><br> → <strong>行为价值不同于权势高低</strong><br> → <strong>口头评价又可能与实际依附冲突</strong><br> → <strong>行还承担关系秩序的作用</strong><br> → <strong>秩序典范也须受到检验</strong><br> → <strong>趋名、趋利都可能改情易性</strong><br> → <strong>一致与坚持仍需内容、分寸和后果的检验。</strong></p><h2 id="四、无足与知和·欲求、分寸与财富六害" tabindex="-1">四、无足与知和·欲求、分寸与财富六害 <a class="header-anchor" href="#四、无足与知和·欲求、分寸与财富六害" aria-label="Permalink to &quot;四、无足与知和·欲求、分寸与财富六害&quot;">​</a></h2><h3 id="原文关键句摘录" tabindex="-1">原文关键句摘录 <a class="header-anchor" href="#原文关键句摘录" aria-label="Permalink to &quot;原文关键句摘录&quot;">​</a></h3><blockquote><p>本节阅读组件展示的是用户提供的关键句，不是本场连续全文。各条按问答推进次序排列，条与条之间存在省略。</p></blockquote>',51)),a(h,{sections:d(T),glossary:l,"default-mode":"classic","aria-label":"盗跖·fourthSection 原文"},null,8,["sections"]),t[12]||(t[12]=i("h3",{id:"字词释义-3",tabindex:"-1"},[e("字词释义 "),i("a",{class:"header-anchor",href:"#字词释义-3","aria-label":'Permalink to "字词释义"'},"​")],-1)),a(n,{items:d(S)},null,8,["items"]),t[13]||(t[13]=i("h3",{id:"语句导读",tabindex:"-1"},[e("语句导读 "),i("a",{class:"header-anchor",href:"#语句导读","aria-label":'Permalink to "语句导读"'},"​")],-1)),a(p,{lines:d(A)},null,8,["lines"]),t[14]||(t[14]=z('<h3 id="深入解读-3" tabindex="-1">深入解读 <a class="header-anchor" href="#深入解读-3" aria-label="Permalink to &quot;深入解读&quot;">​</a></h3><h4 id="一、富贵与养生-先认真看待财富的作用" tabindex="-1">一、富贵与养生：先认真看待财富的作用 <a class="header-anchor" href="#一、富贵与养生-先认真看待财富的作用" aria-label="Permalink to &quot;一、富贵与养生：先认真看待财富的作用&quot;">​</a></h4><p>无足提出一条关系：</p><p><strong>富</strong> → <strong>人归之</strong> → <strong>人下之</strong> → <strong>人贵之</strong> → <strong>长生、安体、乐意。</strong></p><p>财富能提供供养，地位能取得帮助，尊重可能支持心意悦乐。这不是只能被嘲笑的主张，物质条件确实可能改善生活。</p><p>需要检验的是：归附是否可靠，尊奉是否保证安全，财富增加是否总使人更自在？</p><p>后面的忧与畏将反过来检验这些环节。</p><h4 id="二、不愿求与不能求-不能只凭结果推断动机" tabindex="-1">二、不愿求与不能求：不能只凭结果推断动机 <a class="header-anchor" href="#二、不愿求与不能求-不能只凭结果推断动机" aria-label="Permalink to &quot;二、不愿求与不能求：不能只凭结果推断动机&quot;">​</a></h4><p>根据所提供的对话解读，无足还怀疑不求富贵是否只是认识不足或无力取得。</p><p>得不到、不去取、宣称不需要，是不同状态，不能相互替代。</p><p>知和也不能只说自己不求，就证明已经看清分寸；取舍仍需说明根据。</p><h4 id="三、不苟为-也不苟不为-两端同时受检验" tabindex="-1">三、不苟为，也不苟不为：两端同时受检验 <a class="header-anchor" href="#三、不苟为-也不苟不为-两端同时受检验" aria-label="Permalink to &quot;三、不苟为，也不苟不为：两端同时受检验&quot;">​</a></h4><blockquote><p>不为苟为，不为苟不为。</p></blockquote><p>不辨根据地求取，与不辨根据地拒绝，都不是本段认可的方向。</p><p>求与辞应回到实际所需、负担与关系，不只为了表现清高，或证明自己有能力取得。</p><p><strong>拒绝本身不自动高尚，获得利益也不自动合宜。</strong></p><h4 id="四、自然欲求-存在不等于无限满足" tabindex="-1">四、自然欲求：存在不等于无限满足 <a class="header-anchor" href="#四、自然欲求-存在不等于无限满足" aria-label="Permalink to &quot;四、自然欲求：存在不等于无限满足&quot;">​</a></h4><blockquote><p>名誉之欲，富贵之求，人之所欲也。</p></blockquote><p>无足要求承认名誉、富贵之求也是实际人情，与第一场盗跖的欲求论相接。</p><p>但需要分开欲求存在、满足方式合宜，以及是否损害自身与他人。</p><p>第一项不能代替后两项。自然之名不构成无限扩张的许可。</p><h4 id="五、不足求之-有余辞之-不受贪廉标签逼迫" tabindex="-1">五、不足求之，有余辞之：不受贪廉标签逼迫 <a class="header-anchor" href="#五、不足求之-有余辞之-不受贪廉标签逼迫" aria-label="Permalink to &quot;五、不足求之，有余辞之：不受贪廉标签逼迫&quot;">​</a></h4><blockquote><p>不足故求之……不自以为贪。<br> 有余故辞之……不自以为廉。</p></blockquote><p>必要求取不应只因害怕贪名而放弃，辞去多余也不必经营成廉名。</p><blockquote><p>廉贪之实，非以迫外也，反监之度。</p></blockquote><p>取舍回到实际分寸，而非固定站在求或辞的一边。</p><p>但“我觉得不足”也不能独占尺度，使取得方式与后果不受检验。</p><p>“动以百姓”等字句保留疑难，不以一种公共治理译法强行统摄全段。</p><h4 id="六、目标不能反伤根本" tabindex="-1">六、目标不能反伤根本 <a class="header-anchor" href="#六、目标不能反伤根本" aria-label="Permalink to &quot;六、目标不能反伤根本&quot;">​</a></h4><blockquote><p>不以美害生，不以事害己。</p></blockquote><p>美好目标、受认可事务，不会自动使其生命代价合理。</p><p>这与前面名位、德目之祸相接，却不是取消行动、责任与必要投入。需要检验的是目标何时反过来吞没自身。</p><h4 id="七、清名也可能伤身-不是从追富退回禁欲" tabindex="-1">七、清名也可能伤身：不是从追富退回禁欲 <a class="header-anchor" href="#七、清名也可能伤身-不是从追富退回禁欲" aria-label="Permalink to &quot;七、清名也可能伤身：不是从追富退回禁欲&quot;">​</a></h4><blockquote><p>为清名而苦体绝甘，约养以持生。</p></blockquote><p>为清名刻意压缩供养，表面拒绝富贵，仍可能受外在评价支配。</p><table tabindex="0"><thead><tr><th>方向</th><th>可能的偏转</th></tr></thead><tbody><tr><td>为富贵不断扩张所有</td><td>财富支配生活</td></tr><tr><td>为清名不断缩减所需</td><td>名誉支配生活</td></tr></tbody></table><p>不能因此否定所有节俭与节制。需要分别辨认动机、程度与后果。</p><h4 id="八、财富无所不利-有用不等于越多越好" tabindex="-1">八、财富无所不利？有用不等于越多越好 <a class="header-anchor" href="#八、财富无所不利-有用不等于越多越好" aria-label="Permalink to &quot;八、财富无所不利？有用不等于越多越好&quot;">​</a></h4><p>无足将财富优势推到“无所不利”，知和则回答：</p><blockquote><p>平为福，有余为害者，物莫不然，而财其甚者也。</p></blockquote><p>平指平适，余指超过合宜限度，不是有钱即害、贫穷即福。</p><p>也不能将所有长期储备归为过量。原文未给出适用于所有人的财富数额，而要求检验新增好处与新增负担的关系。</p><h4 id="九、财富六害-安体乐意的承诺受到后果检验" tabindex="-1">九、财富六害：安体乐意的承诺受到后果检验 <a class="header-anchor" href="#九、财富六害-安体乐意的承诺受到后果检验" aria-label="Permalink to &quot;九、财富六害：安体乐意的承诺受到后果检验&quot;">​</a></h4><p>下表依据用户提供的解读概括，<strong>不是未提供原文的逐字翻译</strong>。</p><table tabindex="0"><thead><tr><th>六害</th><th>所供解读概括的方向</th><th>所揭示的问题</th></tr></thead><tbody><tr><td>乱</td><td>享用不断牵引心意，忘却所务</td><td>生活失去重心</td></tr><tr><td>苦</td><td>膨胀的气势与所有成为负重</td><td>所有越多，所负可能越重</td></tr><tr><td>疾</td><td>贪财、贪权与身心失调相连</td><td>财富不自动转为身体安适</td></tr><tr><td>辱</td><td>逐利不退，执着不舍</td><td>维护所得反使处境难堪</td></tr><tr><td>忧</td><td>积而不用，仍求增加</td><td>数量增长却没有足感</td></tr><tr><td>畏</td><td>内外防备，害怕侵夺</td><td>拥有扩大防失与不安</td></tr></tbody></table><p>可见一条变化：享用牵引、所有成负担、贪取失调、执着不退，继而忧虑与害怕失去。</p><p>这回答无足的养生承诺：财富本可供养，也可能使身心更不安。不是每个富人必然具有六害。</p><h4 id="十、取得与受用-积累不保证安顿" tabindex="-1">十、取得与受用：积累不保证安顿 <a class="header-anchor" href="#十、取得与受用-积累不保证安顿" aria-label="Permalink to &quot;十、取得与受用：积累不保证安顿&quot;">​</a></h4><p>已经取得而不能安心受用，已经超过所需而仍不断求增，财富便从生活手段变成维护目标。</p><p>但有根据的准备、长期规划与没有终点的增加，不应混同。</p><p>同样，人们因财富归附，不保证关系不随财富改变；受到看重，也不保证心意安定。</p><h3 id="本节脉络-2" tabindex="-1">本节脉络 <a class="header-anchor" href="#本节脉络-2" aria-label="Permalink to &quot;本节脉络&quot;">​</a></h3><p><strong>财富似可安体乐意</strong><br> → <strong>求与不求都需要根据</strong><br> → <strong>实际欲求不能被否认</strong><br> → <strong>欲求仍须分寸，不受贪廉名号逼迫</strong><br> → <strong>追富与求清名都可能伤身</strong><br> → <strong>财富有用，不等于无所不利</strong><br> → <strong>以六害检验过量如何反伤生活。</strong></p><p>本场不是从欲求退回禁欲，而是从欲求推进到分寸。</p><h2 id="全篇脉络·四节阅读地图" tabindex="-1">全篇脉络·四节阅读地图 <a class="header-anchor" href="#全篇脉络·四节阅读地图" aria-label="Permalink to &quot;全篇脉络·四节阅读地图&quot;">​</a></h2><p>全篇包含三场对话。第一场在本文分成前后两节，便于保持行动与反击关系；这不表示原文另有四场对话。</p><table tabindex="0"><thead><tr><th>对话</th><th>入口</th><th>主要争点</th><th>收束方向</th></tr></thead><tbody><tr><td>孔子与盗跖</td><td>孔子试图促成改变</td><td>教化、封侯与圣贤传统能否使人信服</td><td>劝说失败，承认贸然涉险</td></tr><tr><td>子张与满苟得</td><td>劝其为行</td><td>行义、求名、趋利及共同秩序</td><td>殉名殉财都可能改情易性</td></tr><tr><td>无足与知和</td><td>劝求富贵</td><td>自然欲求、财富与养生</td><td>以分寸与实际后果检验求辞</td></tr></tbody></table><p><strong>教化凭什么要求人改变？</strong><br> → <strong>所推崇的名义与实际行为是否一致？</strong><br> → <strong>行义怎样区别于求名，求利又如何接受检验？</strong><br> → <strong>不同目标是否都可能吞没情性与生命？</strong><br> → <strong>承认欲求之后，怎样辨认不足与有余？</strong><br> → <strong>财富与清名，是否真正支持安体乐意？</strong></p><p>这是分析上的贯通，不表示三场是同一事件，也不表示后一人物逐项回答了前一人物。</p><h2 id="三问解读" tabindex="-1">三问解读 <a class="header-anchor" href="#三问解读" aria-label="Permalink to &quot;三问解读&quot;">​</a></h2><h3 id="第一问·《盗跖》是在全面否定教化与道德吗" tabindex="-1">第一问·《盗跖》是在全面否定教化与道德吗？ <a class="header-anchor" href="#第一问·《盗跖》是在全面否定教化与道德吗" aria-label="Permalink to &quot;第一问·《盗跖》是在全面否定教化与道德吗？&quot;">​</a></h3><p>不能这样概括。</p><p>全篇使教化者、义士及忠信廉义等名号接受实际检验，但质疑典范、揭露极端代价，并不自动证明所有教导与行为规范无价值。</p><p>子张提出的共同秩序问题，也不能仅凭圣王反例就算已经解决。</p><p>更稳定的阅读方向是：<strong>名号不能免除行为、根据与后果的检验。</strong></p><table tabindex="0"><thead><tr><th>检验层次</th><th>所问的问题</th></tr></thead><tbody><tr><td>名称与行为</td><td>被称为圣贤、义士者实际怎样行？</td></tr><tr><td>言论与实践</td><td>所赞、所贬是否进入自己的选择？</td></tr><tr><td>目标与后果</td><td>名义、财富实际怎样影响生命与关系？</td></tr></tbody></table><h3 id="第二问·强调情性与尊生-是否意味着欲望都应满足" tabindex="-1">第二问·强调情性与尊生，是否意味着欲望都应满足？ <a class="header-anchor" href="#第二问·强调情性与尊生-是否意味着欲望都应满足" aria-label="Permalink to &quot;第二问·强调情性与尊生，是否意味着欲望都应满足？&quot;">​</a></h3><p>不是。</p><p>盗跖提出实际欲求与寿命，满苟得反省名财改变情性，知和进一步要求不违其度。</p><p>情、性、天、寿命、度彼此相接，却不能全部互换：</p><ul><li><strong>情</strong>涉及实际感受、欲求与倾向；</li><li><strong>性、天</strong>涉及本然禀赋与生活根据；</li><li><strong>生、寿命</strong>涉及身体与生命；</li><li><strong>度、和</strong>涉及协调、限度与取舍。</li></ul><p>欲求存在不等于满足方式已经合宜。无限追富与为清名苦身，也可能具有同样受外在目标支配的结构。</p><p><strong>不足可求，有余可辞；求与辞都不能只靠标签决定。</strong></p><h3 id="第三问·孔子败退-是否证明盗跖全对-怎样看待守节的生命代价" tabindex="-1">第三问·孔子败退，是否证明盗跖全对？怎样看待守节的生命代价？ <a class="header-anchor" href="#第三问·孔子败退-是否证明盗跖全对-怎样看待守节的生命代价" aria-label="Permalink to &quot;第三问·孔子败退，是否证明盗跖全对？怎样看待守节的生命代价？&quot;">​</a></h3><p>两个问题都不能只按结局裁定。</p><p>孔子失败包含论辩挫败，也包含暴力威胁与惊惧，没有逐项认同盗跖的全部史事、推论及行为。</p><p>同样，守节造成巨大代价，需要被看见；但从代价巨大到所守毫无价值，还需要进一步判断。</p><p>尤须保留三项难题：</p><ol><li>**批评者是否实践自己的尺度？**盗跖所赞不相害，与自身侵暴不一致。</li><li>**后果与原因是否充分连接？**发生不幸不自动证明教化造成全部不幸。</li><li>**保全自身如何兼顾他人？**不能用自身安适遮蔽他人的生命与关系。</li></ol><p>批评者有过，不使批评自动无效；能提出批评，也不使自己的行为自动正当。</p><h2 id="现代思考与启发" tabindex="-1">现代思考与启发 <a class="header-anchor" href="#现代思考与启发" aria-label="Permalink to &quot;现代思考与启发&quot;">​</a></h2><p>以下为文本引出的实践参照，不是原文规定的固定程序。</p><h3 id="一、劝说先辨认条件" tabindex="-1">一、劝说先辨认条件 <a class="header-anchor" href="#一、劝说先辨认条件" aria-label="Permalink to &quot;一、劝说先辨认条件&quot;">​</a></h3><p>不只问自己有无理由，还应问：</p><ul><li>对方是否愿意听？</li><li>是否共享基本评价尺度？</li><li>所提供的好处是否符合对方所需？</li><li>是否安全、是否适合直接接触？</li></ul><p>有责任不等于能保证结果，有理由也不等于应贸然进入危险处境。</p><h3 id="二、目标应接受实际生活检验" tabindex="-1">二、目标应接受实际生活检验 <a class="header-anchor" href="#二、目标应接受实际生活检验" aria-label="Permalink to &quot;二、目标应接受实际生活检验&quot;">​</a></h3><p>不只看目标高尚、利益可观，也看：</p><ul><li>真实所需是什么；</li><li>已得能否安心受用；</li><li>增加了哪些身体、时间与关系负担；</li><li>是否越追求越没有终点。</li></ul><p>财富可以改善生活，不能据此推成越多越好。清名可能值得尊重，也不能据此要求刻意苦身。</p><h3 id="三、一致还需内容与处境的检验" tabindex="-1">三、一致还需内容与处境的检验 <a class="header-anchor" href="#三、一致还需内容与处境的检验" aria-label="Permalink to &quot;三、一致还需内容与处境的检验&quot;">​</a></h3><p>言行冲突需要反省，贯彻到底也不自动合宜。</p><p>可以问：所持内容是否有根据，是否伤害原想照料的人，能否调整方法而不放弃根本？</p><p>不固化姿态，不等于取消责任；保留调整，也不等于随意为自己开脱。</p><h3 id="四、对自己使用同一尺度" tabindex="-1">四、对自己使用同一尺度 <a class="header-anchor" href="#四、对自己使用同一尺度" aria-label="Permalink to &quot;四、对自己使用同一尺度&quot;">​</a></h3><p>不以别人的问题为自己的免责理由，不只用不相害、尊生与全真批评他人。</p><p>检验说话者与论说可以分开：不盲从身份，也不因身份有过便拒绝分析所有观点。</p><h3 id="五、不以困苦与死亡设置道德门槛" tabindex="-1">五、不以困苦与死亡设置道德门槛 <a class="header-anchor" href="#五、不以困苦与死亡设置道德门槛" aria-label="Permalink to &quot;五、不以困苦与死亡设置道德门槛&quot;">​</a></h3><p>可以理解操守，同时寻找安全的拒绝与退出方式；可以尊重节制，同时承认物质保障与求助需要。</p><p>看见生命代价，不等于否定所有原则；肯定原则，也不等于要求任何人复制极端结局。</p><h2 id="与《让王》对读" tabindex="-1">与《让王》对读 <a class="header-anchor" href="#与《让王》对读" aria-label="Permalink to &quot;与《让王》对读&quot;">​</a></h2><table tabindex="0"><thead><tr><th>比较项</th><th>《让王》</th><th>《盗跖》</th></tr></thead><tbody><tr><td>常见形式</td><td>辞让、退处、辞赏</td><td>论辩、反击、揭露</td></tr><tr><td>入口</td><td>所受是否合宜，是否伤生</td><td>名义是否可信，目标是否吞没自身</td></tr><tr><td>名位</td><td>贵重不等于值得接受</td><td>也可能被理解为收纳、利诱与成功后的认可</td></tr><tr><td>贫富</td><td>贫不必是病，无位不必是耻</td><td>富不必安乐，求清名苦身也不合宜</td></tr><tr><td>操守与生命</td><td>尊生与守节并存</td><td>更尖锐揭出守节的生命代价</td></tr></tbody></table><p>两篇相接处是求与辞都应有根据，身份不能代替实际判断。</p><p>但《让王》肯定伯夷叔齐之节，此处盗跖却批评其系名轻死，不能用一句话抹平。</p><p>对读应保留：重视操守怎样不遮蔽生命代价，重视生命又怎样不抹去所守价值？</p><p>满苟得与知和也不是盗跖的简单重复。满苟得把自己的利纳入检验，知和则进一步补上欲求分寸的问题。</p><h2 id="论辩方法与阅读辨析" tabindex="-1">论辩方法与阅读辨析 <a class="header-anchor" href="#论辩方法与阅读辨析" aria-label="Permalink to &quot;论辩方法与阅读辨析&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方法</th><th>作用</th><th>需要检查</th></tr></thead><tbody><tr><td>反问</td><td>动摇习见判断</td><td>不等于已经完成证明</td></tr><tr><td>古史反例</td><td>揭出典范矛盾</td><td>史事、背景与代表范围</td></tr><tr><td>极端结局</td><td>显示生命代价</td><td>能否代表所有同类实践</td></tr><tr><td>名号反转</td><td>质疑盗、诸侯、君子等标签</td><td>不转成自我免责</td></tr><tr><td>言行对照</td><td>检验评价与选择</td><td>交往不必等于全面认可</td></tr><tr><td>后果检验</td><td>将目标拉回生活</td><td>因果是否充分</td></tr></tbody></table><p>尤须保留疑义的字句：</p><ul><li>第一场：“穴室枢户”“包𫗦”“避席反走”“耻不取焉”“孰论之”“离名”“料虎头”“编虎须”。</li><li>第二场：“多信者显”“吾日与子讼于无约”及后半韵语；“匡子”等人物所指。</li><li>第三场：“动以百姓”“反监之度”等；当前原文材料为摘录，不能将解读补作连续全文。</li></ul><p>全篇发言分属不同人物，不能直接合并为没有差异的一套“庄子主张”。故事中的古史、制度与人物事迹若需历史核验，应另行处理。</p><h2 id="关键词索引" tabindex="-1">关键词索引 <a class="header-anchor" href="#关键词索引" aria-label="Permalink to &quot;关键词索引&quot;">​</a></h2><p>详释见各节词条，以下按论题归组。</p><h3 id="第一场-教导、求见与反击" tabindex="-1">第一场｜教导、求见与反击 <a class="header-anchor" href="#第一场-教导、求见与反击" aria-label="Permalink to &quot;第一场｜教导、求见与反击&quot;">​</a></h3><ul><li><strong>人物与场景</strong>：柳下季、盗跖、从卒九千人、侵暴、穴室枢户、入保。</li><li><strong>教导条件</strong>：诏、往说之、距敌、饰非、必无往。</li><li><strong>求见与威势</strong>：谒者、通、得幸于季、望履幕下、避席反走、案剑、瞋目、乳虎。</li><li><strong>称誉与身份</strong>：三德、知维天地、辩诸物、南面称孤、耻不取焉、更始、昆弟。</li><li><strong>利益与收纳</strong>：规以利、恒民、恒民畜我、遗德、置锥之地。</li><li><strong>古史与生命代价</strong>：陵弱、菹、偏枯、羑里、孰论之、离名轻死、本养寿命。</li><li><strong>情性与寿命</strong>：有时之具、骐骥、说其志意、全真。</li><li><strong>败退与冒险</strong>：辔、芒然、轼、阙然、无病自灸、料虎头、编虎须。</li></ul><h3 id="第二场-行义、评价与殉名殉财" tabindex="-1">第二场｜行义、评价与殉名殉财 <a class="header-anchor" href="#第二场-行义、评价与殉名殉财" aria-label="Permalink to &quot;第二场｜行义、评价与殉名殉财&quot;">​</a></h3><ul><li><strong>为行与收益</strong>：盍、为行、不信、不任、多信者显、几在。</li><li><strong>内在根据</strong>：抱其天、监于道。</li><li><strong>价值与表现</strong>：臧聚、怍色、变容易色、称不足。</li><li><strong>言行冲突</strong>：受币、行则下之、悖战、拂。</li><li><strong>关系秩序</strong>：疏戚、五纪六位、王季为适。</li><li><strong>名财与情性</strong>：殉、吾日与子讼于无约。</li><li><strong>韵语方向</strong>：而天、而行、而义、若枉若直、消息、圆机、无成而义。</li><li><strong>实践后果</strong>：抉眼、直躬证父、鲍子、申子、匡子、必其行、离其患。</li></ul><h3 id="第三场-求辞、分寸与财富" tabindex="-1">第三场｜求辞、分寸与财富 <a class="header-anchor" href="#第三场-求辞、分寸与财富" aria-label="Permalink to &quot;第三场｜求辞、分寸与财富&quot;">​</a></h3><ul><li><strong>富贵承诺</strong>：无足、知和、兴名就利、人归之、下之、见下贵、安体乐意。</li><li><strong>取舍根据</strong>：苟为、苟不为、度、反监之度、迫外。</li><li><strong>贪廉名号</strong>：不自以为贪、不自以为廉。</li><li><strong>伤生与苦身</strong>：美、事、苦体绝甘、约养。</li><li><strong>适量与过量</strong>：平、有余。</li><li><strong>实际后果</strong>：六害——乱、苦、疾、辱、忧、畏。</li></ul><h2 id="核心句速查" tabindex="-1">核心句速查 <a class="header-anchor" href="#核心句速查" aria-label="Permalink to &quot;核心句速查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>核心句</th><th>阅读重点</th><th>避免的误读</th></tr></thead><tbody><tr><td>万民苦之</td><td>受害者是不可省略的背景</td><td>雄辩使暴行正当</td></tr><tr><td>弟不受兄之教，将奈之何</td><td>责任不保证结果</td><td>无需再关心</td></tr><tr><td>顺吾意则生，逆吾心则死</td><td>论辩受暴力条件限制</td><td>只是平等逻辑辩论</td></tr><tr><td>尊将军为诸侯，与天下更始</td><td>利益与秩序一起促成改变</td><td>方案已证实可行</td></tr><tr><td>规我以利而恒民畜我</td><td>给予也可能被理解为收纳</td><td>一切给予都是控制</td></tr><tr><td>何故不谓子为盗丘</td><td>名号与行为的一致性</td><td>别人有过便可免责</td></tr><tr><td>离名轻死，不念本养寿命</td><td>社会尊高与生命代价</td><td>操守全部无价值</td></tr><tr><td>说其志意、养其寿命</td><td>实际情性需要安顿</td><td>欲望无限满足</td></tr><tr><td>非可以全真也</td><td>所行须接受生命情性检验</td><td>盗跖已践行尺度</td></tr><tr><td>无病而自灸</td><td>劝说者自认涉险</td><td>对方全部正确</td></tr><tr><td>贵贱之分，在行之美恶</td><td>权势不独占价值</td><td>称誉即完整证明</td></tr><tr><td>论则贱之，行则下之</td><td>言论与选择的裂缝</td><td>一切交往等于全面认可</td></tr><tr><td>成者为首，不成者为尾</td><td>现实认可与权势</td><td>成功自动正当</td></tr><tr><td>小人殉财，君子殉名</td><td>不同目标可能同样伤性</td><td>一切义利完全相同</td></tr><tr><td>与时消息，执而圆机</td><td>保留调整与转圜</td><td>取消所有原则</td></tr><tr><td>正其言，必其行</td><td>一致还需内容检验</td><td>贯彻到底必然合宜</td></tr><tr><td>不为苟为，不为苟不为</td><td>求与辞都需根据</td><td>拒绝天然高尚</td></tr><tr><td>不足故求之，有余故辞之</td><td>依实际分寸取舍</td><td>自称不足即可免责</td></tr><tr><td>不以美害生，不以事害己</td><td>目标不能反伤根本</td><td>一切付出都应取消</td></tr><tr><td>苦体绝甘，约养以持生</td><td>清名也可能支配生活</td><td>一切节制都有害</td></tr><tr><td>平为福，有余为害</td><td>有用不同于越多越好</td><td>贫穷必然幸福</td></tr><tr><td>今富人有此六害</td><td>后果检验安体乐意</td><td>每个富人必然如此</td></tr></tbody></table><h2 id="四节·一句话回顾" tabindex="-1">四节·一句话回顾 <a class="header-anchor" href="#四节·一句话回顾" aria-label="Permalink to &quot;四节·一句话回顾&quot;">​</a></h2><ol><li><strong>孔子往见</strong>：带着封侯方案去劝人，先被“名”挡住了门。</li><li><strong>盗跖反击</strong>：以名位、情性与有限生命反问——你所推崇的，凭什么要求我改？</li><li><strong>子张与满苟得</strong>：行义与求名、求利都可能改情易性，殉名与殉财并无高下之分。</li><li><strong>无足与知和</strong>：承认欲求之后，仍要用分寸与实际后果来检验贫富与辞受。</li></ol><h2 id="一句话读懂《盗跖》" tabindex="-1">一句话读懂《盗跖》 <a class="header-anchor" href="#一句话读懂《盗跖》" aria-label="Permalink to &quot;一句话读懂《盗跖》&quot;">​</a></h2><blockquote><p><strong>「孰论之以为邪？孰论之以为正？」</strong></p></blockquote><p>《盗跖》的锋利不在骂人，而在逼问：谁有资格替你定正邪？一旦这个问题被提出，教化者、求名者与逐利者就都站在同一张秤上——所说与所行是否一致，所求是否符合所需，所守是否仍在照料生命。</p><h2 id="参考来源" tabindex="-1">参考来源 <a class="header-anchor" href="#参考来源" aria-label="Permalink to &quot;参考来源&quot;">​</a></h2><h3 id="本文直接依据" tabindex="-1">本文直接依据 <a class="header-anchor" href="#本文直接依据" aria-label="Permalink to &quot;本文直接依据&quot;">​</a></h3><ul><li>用户提供的《庄子·盗跖》原文、字词注解、逐场解读与全篇总整理。</li><li>孔子与盗跖、子张与满苟得两场采用所供连续原文。</li><li>无足与知和一场采用所供关键句摘录；其问答脉络及六害说明依据所供解读，不作为缺失全文的替代。</li></ul><h3 id="文内对读" tabindex="-1">文内对读 <a class="header-anchor" href="#文内对读" aria-label="Permalink to &quot;文内对读&quot;">​</a></h3><ul><li>《庄子·让王》：辞受、知足、尊生、守节及生命代价。</li><li>管仲、田常、子路、伯夷叔齐、比干、子胥等相关传统故事：本文首先解释其在论辩中的作用，未进行完整史料校核。</li><li>文中“《书》曰”保留所供形式，不强定今本《尚书》出处。</li></ul><p>本文未列未经核验的版本页码、人物年表、制度细节或地望定论。疑难字词保留解释限度，不将一种贯通读法当作唯一训释。</p><h2 id="全篇最后一问" tabindex="-1">全篇最后一问 <a class="header-anchor" href="#全篇最后一问" aria-label="Permalink to &quot;全篇最后一问&quot;">​</a></h2><p>篇首先有一次失败的劝行：</p><p><strong>孔子往见，欲说而止。</strong></p><p>第二节是对方的反击：</p><p><strong>「今子修文武之道，掌天下之辩，以教后世。」</strong></p><p>最后两节换了人物，问题却还在原处：</p><p><strong>行义与求名，能分得开吗？</strong></p><p><strong>欲求既有其自然，界线又在哪里？</strong></p><p>于是最后可以这样问自己：</p><p><strong>我所推崇的东西，我自己做到了吗？</strong></p><p><strong>我为他人的好处所做的安排，问过对方需要什么吗？</strong></p><p><strong>我的坚持，是在照料生命，还是已经反过来消耗它？</strong></p><h2 id="全篇收束·锋利之后-仍要分辨" tabindex="-1">全篇收束·锋利之后，仍要分辨 <a class="header-anchor" href="#全篇收束·锋利之后-仍要分辨" aria-label="Permalink to &quot;全篇收束·锋利之后，仍要分辨&quot;">​</a></h2><p>《盗跖》不只是把义换成利，也不是把节制换成纵欲。</p><p>它使教化者不能仅凭圣贤名号免于审问，使趋名与趋利都接受情性检验，也使欲求不能凭自然之名无限扩张、辞让不能凭清名之名不断苦身。</p><p>最后留下的不是一种必须选择的身份，而是持续的判断：</p><p><strong>所说与所行是否一致？所求是否符合所需？所守是否仍在照料生命与关系？所谓美好，是否已反过来伤害生活的根本？</strong></p>',149))])}}});export{G as __pageData,E as default};
